}

#[derive(Clone, Debug, PartialEq)]
pub enum CodeKind {
    Indented,
    Fenced(String),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Tag {
    Paragraph,
    Heading { level: u8, id: Option<String> },
    BlockQuote,
    CodeBlock(CodeKind),
    HtmlBlock,
    List(Option<u64>),
    Item,
    Table(Vec<Alignment>),
    TableHead,
    TableRow,
    TableCell,
    Emphasis,
    Strong,
    Strikethrough,
    Link { dest: String, title: String, kind: LinkKind },
    Image { dest: String, title: String },
    MetadataBlock,
}

#[derive(Clone, Debug, PartialEq, Copy)]
pub enum LinkKind {
    Inline,
    Reference,
    Autolink,
    Email,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Event {
    Start(Tag),
    End(Tag),
    Text(String),
    Code(String),
    Html(String),
    InlineHtml(String),
    SoftBreak,
    HardBreak,
    Rule,
    TaskListMarker(bool),
}

#[derive(Clone, Copy, Debug, Default)]
pub struct Options {
    pub tables: bool,
    pub strikethrough: bool,
    pub tasklists: bool,
    pub heading_attributes: bool,
    pub metadata: bool,
}

impl Options {
    pub fn gfm() -> Options {
        Options { tables: true, strikethrough: true, tasklists: true, heading_attributes: false, metadata: false }
    }
}

pub fn parse(text: &str, opts: Options) -> Vec<(Event, Range<usize>)> {
    block::parse_document(text, opts)
}

/// Is the byte ASCII punctuation (CommonMark definition)?
pub fn is_ascii_punct(b: u8) -> bool {
    matches!(b, b'!'..=b'/' | b':'..=b'@' | b'['..=b'`' | b'{'..=b'~')
}

/// Normalize a link label for reference matching.
pub fn normalize_label(s: &str) -> String {
    let mut out = String::new();
    let mut ws = false;
    for c in s.trim().chars() {
        if c.is_whitespace() {
            ws = true;
        } else {
            if ws && !out.is_empty() {
                out.push(' ');
            }
            ws = false;
            for l in c.to_lowercase() {
                out.push(l);
            }
        }
    }
    // Unicode case fold approximations
    out.replace('ß', "ss").replace('ẞ', "ss")
}
