{"command":"cd /workspace/src/md && cat > block.rs <<'EOF'
use super::inline;
use super::*;
use std::collections::HashMap;

#[derive(Clone, Debug)]
pub(crate) struct Seg {
    pub prefix: usize,
    pub start: usize,
    pub end: usize,
}

#[derive(Clone, Debug)]
enum Kind {
    Document,
    BlockQuote,
    List { ordered: bool, bullet: u8, start: u64, tight: bool },
    Item { marker_offset: usize, padding: usize },
    Paragraph,
    Heading { level: u8, id: Option<String> },
    ThematicBreak,
    CodeBlock { fenced: bool, fence_char: u8, fence_len: usize, fence_offset: usize, info: String },
    HtmlBlock { html_type: u8 },
    Table { aligns: Vec<Alignment>, ncols: usize },
    Metadata,
}

#[derive(Clone, Debug)]
struct Node {
    kind: Kind,
    parent: usize,
    children: Vec<usize>,
    open: bool,
    start: usize,
    start_line: usize,
    last_line_blank: bool,
    last_line_checked: bool,
    lines: Vec<Seg>,
    removed: bool,
}

#[derive(Clone, Debug)]
pub(crate) struct LinkDef {
    pub dest: String,
    pub title: String,
}

struct P<'a> {
    src: &'a str,
    b: &'a [u8],
    opts: Options,
    nodes: Vec<Node>,
    tip: usize,
    old_tip: usize,
    last_matched: usize,
    all_closed: bool,
    ls: usize,
    le: usize,
    offset: usize,
    column: usize,
    next_nonspace: usize,
    next_nonspace_column: usize,
    indent: usize,
    indented: bool,
    blank: bool,
    partially_consumed_tab: bool,
    line_number: usize,
    refs: HashMap<String, LinkDef>,
    lines: Vec<(usize, usize)>,
    cur_line_idx: usize,
    skip_until_line: usize,
}

const CODE_INDENT: usize = 4;

fn is_space_or_tab(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

pub(crate) fn split_lines(src: &str) -> Vec<(usize, usize)> {
    let b = src.as_bytes();
    let mut lines = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'\n' {
            let mut end = i;
            if end > start && b[end - 1] == b'\r' {
                end -= 1;
            }
            lines.push((start, end));
            start = i + 1;
        }
        i += 1;
    }
    if start < b.len() {
        let mut end = b.len();
        if end > start && b[end - 1] == b'\r' {
            end -= 1;
        }
        lines.push((start, end));
    }
    lines
}

static BLOCK_TAGS: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center", "col",
    "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure",
    "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6", "head", "header", "hr",
    "html", "iframe", "legend", "li", "link", "main", "menu", "menuitem", "nav", "noframes", "ol",
    "optgroup", "option", "p", "param", "search", "section", "summary", "table", "tbody", "td", "tfoot",
    "th", "thead", "title", "tr", "track", "ul",
];

impl<'a> P<'a> {
    fn new_node(&mut self, kind: Kind, parent: usize, start: usize) -> usize {
        let id = self.nodes.len();
        self.nodes.push(Node {
            kind,
            parent,
            children: Vec::new(),
            open: true,
            start,
            start_line: self.line_number,
            last_line_blank: false,
            last_line_checked: false,
            lines: Vec::new(),
            removed: false,
        });
        if id != 0 {
            self.nodes[parent].children.push(id);
        }
        id
    }

    fn peek(&self, pos: usize) -> u8 {
        if pos < self.le {
            self.b[pos]
        } else {
            0
        }
    }

    fn find_next_nonspace(&mut self) {
        let mut i = self.offset;
        let mut cols = self.column;
        while i < self.le {
            let c = self.b[i];
            if c == b' ' {
                i += 1;
                cols += 1;
            } else if c == b'\t' {
                i += 1;
                cols += 4 - (cols % 4);
            } else {
                break;
            }
        }
        self.blank = i >= self.le;
        self.next_nonspace = i;
        self.next_nonspace_column = cols;
        self.indent = self.next_nonspace_column - self.column;
        self.indented = self.indent >= CODE_INDENT;
    }

    fn advance_next_nonspace(&mut self) {
        self.offset = self.next_nonspace;
        self.column = self.next_nonspace_column;
        self.partially_consumed_tab = false;
    }

    fn advance_offset(&mut self, mut count: usize, columns: bool) {
        while count > 0 && self.offset < self.le {
            let c = self.b[self.offset];
            if c == b'\t' {
                let chars_to_tab = 4 - (self.column % 4);
                if columns {
                    self.partially_consumed_tab = chars_to_tab > count;
                    let adv = chars_to_tab.min(count);
                    self.column += adv;
                    if !self.partially_consumed_tab {
                        self.offset += 1;
                    }
                    count -= adv;
                } else {
                    self.partially_consumed_tab = false;
                    self.column += chars_to_tab;
                    self.offset += 1;
                    count -= 1;
                }
            } else {
                self.partially_consumed_tab = false;
                self.offset += 1;
                self.column += 1;
                count -= 1;
            }
        }
    }

    fn accepts_lines(&self, id: usize) -> bool {
        matches!(
            self.nodes[id].kind,
            Kind::Paragraph | Kind::CodeBlock { .. } | Kind::HtmlBlock { .. } | Kind::Table { .. }
        )
    }

    fn can_contain(&self, parent: usize, child: &Kind) -> bool {
        match &self.nodes[parent].kind {
            Kind::Document | Kind::BlockQuote | Kind::Item { .. } => !matches!(child, Kind::Item { .. }),
            Kind::List { .. } => matches!(child, Kind::Item { .. }),
            _ => false,
        }
    }

    fn add_child(&mut self, kind: Kind, start: usize) -> usize {
        while !self.can_contain(self.tip, &kind) {
            let t = self.tip;
            self.finalize(t);
        }
        let id = self.new_node(kind, self.tip, start);
        self.tip = id;
        id
    }

    fn add_line(&mut self) {
        let mut prefix = 0;
        if self.partially_consumed_tab {
            self.offset += 1;
            let chars_to_tab = 4 - (self.column % 4);
            prefix = chars_to_tab;
        }
        let seg = Seg { prefix, start: self.offset, end: self.le };
        let t = self.tip;
        self.nodes[t].lines.push(seg);
    }

    fn close_unmatched_blocks(&mut self) {
        if !self.all_closed {
            while self.old_tip != self.last_matched {
                let parent = self.nodes[self.old_tip].parent;
                let ot = self.old_tip;
                self.finalize(ot);
                self.old_tip = parent;
            }
            self.all_closed = true;
        }
    }

    fn line_text(&self, s: &Seg) -> String {
        let mut t = " ".repeat(s.prefix);
        t.push_str(&self.src[s.start..s.end]);
        t
    }

    fn finalize(&mut self, id: usize) {
        let parent = self.nodes[id].parent;
        self.nodes[id].open = false;
        match self.nodes[id].kind.clone() {
            Kind::Paragraph => {
                self.extract_refs(id);
                if self.nodes[id].lines.is_empty() {
                    self.remove_node(id);
                }
            }
            Kind::CodeBlock { fenced: false, .. } => {
                // strip trailing blank lines
                while let Some(last) = self.nodes[id].lines.last() {
                    let t = self.line_text(last);
                    if t.trim_matches(|c| c == ' ' || c == '\t').is_empty() {
                        self.nodes[id].lines.pop();
                    } else {
                        break;
                    }
                }
            }
            Kind::List { ordered, bullet, start, .. } => {
                let tight = self.compute_tight(id);
                self.nodes[id].kind = Kind::List { ordered, bullet, start, tight };
            }
            _ => {}
        }
        if id != 0 {
            self.tip = parent;
        }
    }

    fn remove_node(&mut self, id: usize) {
        self.nodes[id].removed = true;
        let parent = self.nodes[id].parent;
        self.nodes[parent].children.retain(|&c| c != id);
    }

    fn ends_with_blank_line(&mut self, mut id: usize) -> bool {
        loop {
            if self.nodes[id].last_line_blank {
                return true;
            }
            let is_list_or_item = matches!(self.nodes[id].kind, Kind::List { .. } | Kind::Item { .. });
            if !self.nodes[id].last_line_checked && is_list_or_item {
                self.nodes[id].last_line_checked = true;
                match self.nodes[id].children.last() {
                    Some(&c) => id = c,
                    None => return false,
                }
            } else {
                self.nodes[id].last_line_checked = true;
                return false;
            }
        }
    }

    fn compute_tight(&mut self, list: usize) -> bool {
        let items = self.nodes[list].children.clone();
        for (i, &item) in items.iter().enumerate() {
            let has_next = i + 1 < items.len();
            if self.ends_with_blank_line(item) && has_next {
                return false;
            }
            let subs = self.nodes[item].children.clone();
            for (j, &sub) in subs.iter().enumerate() {
                let sub_next = j + 1 < subs.len();
                if self.ends_with_blank_line(sub) && (has_next || sub_next) {
                    return false;
                }
            }
        }
        true
    }

    // ---- reference definitions ----
    fn extract_refs(&mut self, id: usize) {
        loop {
            let segs = self.nodes[id].lines.clone();
            if segs.is_empty() {
                return;
            }
            let first = self.line_text(&segs[0]);
            if !first.starts_with('[') {
                return;
            }
            // Build joined text and line boundaries
            let mut joined = String::new();
            let mut bounds = Vec::new();
            for s in &segs {
                joined.push_str(&self.line_text(s));
                joined.push('\n');
                bounds.push(joined.len());
            }
            match parse_ref_def(&joined) {
                Some((consumed, label, def)) => {
                    // consumed must end at a line boundary
                    let nlines = bounds.iter().position(|&b| b == consumed).map(|p| p + 1);
                    let nlines = match nlines {
                        Some(n) => n,
                        None => return,
                    };
                    let key = normalize_label(&label);
                    if !key.is_empty() {
                        self.refs.entry(key).or_insert(def);
                    }
                    self.nodes[id].lines.drain(0..nlines);
                }
                None => return,
            }
        }
    }

    // ---- block starts ----
    fn try_block_starts(&mut self, container: &mut usize) -> u8 {
        // returns 0 = none, 1 = container, 2 = leaf
        let c = self.peek(self.next_nonspace);
        let tipkind_para = matches!(self.nodes[*container].kind, Kind::Paragraph);
        let container_is_table = matches!(self.nodes[*container].kind, Kind::Table { .. });
        let interrupting = tipkind_para || container_is_table;
        // block quote
        if !self.indented && c == b'>' {
            self.advance_next_nonspace();
            self.advance_offset(1, false);
            if is_space_or_tab(self.peek(self.offset)) {
                self.advance_offset(1, true);
            }
            self.close_unmatched_blocks();
            let s = self.next_nonspace;
            *container = self.add_child(Kind::BlockQuote, s);
            return 1;
        }
        // ATX heading
        if !self.indented && c == b'#' {
            if let Some((level, cstart, cend, id)) = self.scan_atx() {
                self.advance_next_nonspace();
                self.close_unmatched_blocks();
                let s = self.next_nonspace;
                let h = self.add_child(Kind::Heading { level, id }, s);
                self.nodes[h].lines.push(Seg { prefix: 0, start: cstart, end: cend });
                self.offset = self.le;
                *container = h;
                return 2;
            }
        }
        // fenced code
        if !self.indented && (c == b'`' || c == b'~') {
            let mut n = 0;
            let mut i = self.next_nonspace;
            while i < self.le && self.b[i] == c {
                n += 1;
                i += 1;
            }
            if n >= 3 {
                let rest = &self.src[i..self.le];
                if !(c == b'`' && rest.contains('`')) {
                    let info = unescape_info(rest.trim_matches(|ch| ch == ' ' || ch == '\t'));
                    let fence_offset = self.indent;
                    self.close_unmatched_blocks();
                    let s = self.next_nonspace;
                    *container = self.add_child(
                        Kind::CodeBlock { fenced: true, fence_char: c, fence_len: n, fence_offset, info },
                        s,
                    );
                    self.offset = self.le;
                    return 2;
                }
            }
        }
        // HTML block
        if !self.indented && c == b'<' {
            let line = &self.src[self.next_nonspace..self.le];
            if let Some(t) = html_block_start(line, tipkind_para) {
                self.close_unmatched_blocks();
                let s = self.next_nonspace;
                *container = self.add_child(Kind::HtmlBlock { html_type: t }, s);
                // don't advance: line content added including leading spaces
                return 2;
            }
        }
        // setext heading
        if !self.indented && tipkind_para && (c == b'=' || c == b'-') {
            let line = &self.src[self.next_nonspace..self.le];
            let t = line.trim_end_matches(|ch| ch == ' ' || ch == '\t');
            if !t.is_empty() && t.bytes().all(|x| x == c) {
                self.close_unmatched_blocks();
                let para = *container;
                self.extract_refs(para);
                if !self.nodes[para].lines.is_empty() {
                    let level = if c == b'=' { 1 } else { 2 };
                    let mut id = None;
                    if self.opts.heading_attributes {
                        // attributes on the last line
                        let last = self.nodes[para].lines.len() - 1;
                        let seg = self.nodes[para].lines[last].clone();
                        let text = &self.src[seg.start..seg.end];
                        let tt = text.trim_end_matches(|ch| ch == ' ' || ch == '\t');
                        if let Some((cut, hid)) = parse_heading_attrs(tt) {
                            let newend = seg.start + cut;
                            self.nodes[para].lines[last].end = newend;
                            id = hid;
                        }
                    }
                    self.nodes[para].kind = Kind::Heading { level, id };
                    self.offset = self.le;
                    return 2;
                } else {
                    // paragraph consisted only of refs: remove it and continue
                    self.remove_node(para);
                    self.tip = self.nodes[para].parent;
                    *container = self.tip;
                    // fall through to other starts
                }
            }
        }
        // thematic break
        if !self.indented && (c == b'*' || c == b'_' || c == b'-') {
            let line = &self.src[self.next_nonspace..self.le];
            if is_thematic_break(line) {
                self.close_unmatched_blocks();
                let s = self.next_nonspace;
                *container = self.add_child(Kind::ThematicBreak, s);
                self.offset = self.le;
                return 2;
            }
        }
        // list item
        let cont_is_list = matches!(self.nodes[*container].kind, Kind::List { .. });
        if !self.indented || cont_is_list {
            if let Some(r) = self.try_list_item(container, interrupting) {
                return r;
            }
        }
        // indented code
        if self.indented && !tipkind_para_tip(self) && !self.blank && !container_is_table {
            self.advance_offset(CODE_INDENT, true);
            self.close_unmatched_blocks();
            let s = self.offset;
            *container = self.add_child(
                Kind::CodeBlock { fenced: false, fence_char: 0, fence_len: 0, fence_offset: 0, info: String::new() },
                s,
            );
            return 2;
        }
        0
    }

    fn scan_atx(&self) -> Option<(u8, usize, usize, Option<String>)> {
        let mut i = self.next_nonspace;
        let mut level = 0;
        while i < self.le && self.b[i] == b'#' {
            level += 1;
            i += 1;
        }
        if level == 0 || level > 6 {
            return None;
        }
        if i < self.le && !is_space_or_tab(self.b[i]) {
            return None;
        }
        // content
        let mut cs = i;
        while cs < self.le && is_space_or_tab(self.b[cs]) {
            cs += 1;
        }
        let mut ce = self.le;
        let mut id = None;
        // trailing whitespace
        while ce > cs && is_space_or_tab(self.b[ce - 1]) {
            ce -= 1;
        }
        if self.opts.heading_attributes {
            let text = &self.src[cs..ce];
            if let Some((cut, hid)) = parse_heading_attrs(text) {
                ce = cs + cut;
                id = hid;
                while ce > cs && is_space_or_tab(self.b[ce - 1]) {
                    ce -= 1;
                }
            }
        }
        // closing sequence
        let mut j = ce;
        while j > cs && self.b[j - 1] == b'#' {
            j -= 1;
        }
        if j < ce {
            if j == cs {
                ce = cs;
            } else if is_space_or_tab(self.b[j - 1]) {
                ce = j;
                while ce > cs && is_space_or_tab(self.b[ce - 1]) {
                    ce -= 1;
                }
            }
        }
        if ce < cs {
            ce = cs;
        }
        Some((level as u8, cs, ce, id))
    }

    fn try_list_item(&mut self, container: &mut usize, interrupting: bool) -> Option<u8> {
        let start_pos = self.next_nonspace;
        let c = self.peek(start_pos);
        let mut bullet = 0u8;
        let mut ordered = false;
        let mut start_num = 0u64;
        let mut marker_end;
        if c == b'*' || c == b'+' || c == b'-' {
            bullet = c;
            marker_end = start_pos + 1;
        } else if c.is_ascii_digit() {
            let mut i = start_pos;
            while i < self.le && self.b[i].is_ascii_digit() && i - start_pos < 9 {
                i += 1;
            }
            if i < self.le && (self.b[i] == b'.' || self.b[i] == b')') && !(i < self.le && self.b[i].is_ascii_digit()) {
                ordered = true;
                start_num = self.src[start_pos..i].parse().unwrap_or(0);
                bullet = self.b[i];
                marker_end = i + 1;
            } else {
                return None;
            }
        } else {
            return None;
        }
        let next = self.peek(marker_end);
        if !(next == 0 || is_space_or_tab(next)) {
            return None;
        }
        if interrupting {
            // cannot interrupt paragraph if empty item or ordered not starting at 1
            let mut k = marker_end;
            while k < self.le && is_space_or_tab(self.b[k]) {
                k += 1;
            }
            if k >= self.le {
                return None;
            }
            if ordered && start_num != 1 {
                return None;
            }
        }
        // thematic break takes precedence (handled earlier)
        // compute padding
        self.advance_next_nonspace();
        let marker_len = marker_end - start_pos;
        self.advance_offset(marker_len, true);
        let spaces_start_col = self.column;
        let spaces_start_offset = self.offset;
        loop {
            self.advance_offset(1, true);
            let nc = self.peek(self.offset);
            if !(self.column - spaces_start_col < 5 && is_space_or_tab(nc)) {
                break;
            }
        }
        let blank_item = self.peek(self.offset) == 0;
        let spaces_after_marker = self.column - spaces_start_col;
        let padding;
        if spaces_after_marker >= 5 || spaces_after_marker < 1 || blank_item {
            padding = marker_len + 1;
            self.column = spaces_start_col;
            self.offset = spaces_start_offset;
            if is_space_or_tab(self.peek(self.offset)) {
                self.advance_offset(1, true);
            }
        } else {
            padding = marker_len + spaces_after_marker;
        }
        let marker_offset = self.indent;
        self.close_unmatched_blocks();
        let tip_is_matching_list = match &self.nodes[self.tip].kind {
            Kind::List { ordered: o, bullet: b, .. } => *o == ordered && *b == bullet,
            _ => false,
        };
        if !tip_is_matching_list {
            let k = Kind::List { ordered, bullet, start: start_num, tight: true };
            self.add_child(k, start_pos);
        }
        let item = self.add_child(Kind::Item { marker_offset, padding }, start_pos);
        *container = item;
        Some(1)
    }

    fn continue_block(&mut self, id: usize) -> u8 {
        // 0 matched, 1 not matched, 2 line consumed
        match self.nodes[id].kind.clone() {
            Kind::Document | Kind::List { .. } => 0,
            Kind::BlockQuote => {
                if !self.indented && self.peek(self.next_nonspace) == b'>' {
                    self.advance_next_nonspace();
                    self.advance_offset(1, false);
                    if is_space_or_tab(self.peek(self.offset)) {
                        self.advance_offset(1, true);
                    }
                    0
                } else {
                    1
                }
            }
            Kind::Item { marker_offset, padding } => {
                if self.blank {
                    if self.nodes[id].children.is_empty() {
                        1
                    } else {
                        self.advance_next_nonspace();
                        0
                    }
                } else if self.indent >= marker_offset + padding {
                    self.advance_offset(marker_offset + padding, true);
                    0
                } else {
                    1
                }
            }
            Kind::Heading { .. } | Kind::ThematicBreak | Kind::Metadata => 1,
            Kind::CodeBlock { fenced, fence_char, fence_len, fence_offset, .. } => {
                if fenced {
                    // closing fence?
                    if self.indent <= 3 && self.peek(self.next_nonspace) == fence_char {
                        let mut i = self.next_nonspace;
                        let mut n = 0;
                        while i < self.le && self.b[i] == fence_char {
                            n += 1;
                            i += 1;
                        }
                        let rest = &self.src[i..self.le];
                        if n >= fence_len && rest.bytes().all(is_space_or_tab) {
                            self.finalize(id);
                            return 2;
                        }
                    }
                    // skip optional spaces of fence offset
                    let mut i = fence_offset;
                    while i > 0 && is_space_or_tab(self.peek(self.offset)) {
                        self.advance_offset(1, true);
                        i -= 1;
                    }
                    0
                } else if self.indent >= CODE_INDENT {
                    self.advance_offset(CODE_INDENT, true);
                    0
                } else if self.blank {
                    self.advance_next_nonspace();
                    0
                } else {
                    1
                }
            }
            Kind::HtmlBlock { html_type } => {
                if self.blank && (html_type == 6 || html_type == 7) {
                    1
                } else {
                    0
                }
            }
            Kind::Paragraph | Kind::Table { .. } => {
                if self.blank {
                    1
                } else {
                    0
                }
            }
        }
    }

    fn try_metadata(&mut self) -> bool {
        let line = &self.src[self.ls..self.le];
        let tl = line.trim_end_matches(|c| c == ' ' || c == '\t');
        let ch = if tl == "---" {
            b'-'
        } else if tl == "+++" {
            b'+'
        } else {
            return false;
        };
        let idx = self.cur_line_idx;
        // next line must exist and be non-blank
        if idx + 1 >= self.lines.len() {
            return false;
        }
        let (ns, ne) = self.lines[idx + 1];
        if self.src[ns..ne].trim().is_empty() {
            return false;
        }
        let mut j = idx + 1;
        while j < self.lines.len() {
            let (s, e) = self.lines[j];
            let t = self.src[s..e].trim_end_matches(|c| c == ' ' || c == '\t');
            let closes = if ch == b'-' { t == "---" || t == "..." } else { t == "+++" };
            if closes {
                // create metadata node
                self.close_unmatched_blocks();
                let start = self.ls;
                let m = self.add_child(Kind::Metadata, start);
                for k in idx + 1..j {
                    let (s2, e2) = self.lines[k];
                    self.nodes[m].lines.push(Seg { prefix: 0, start: s2, end: e2 });
                }
                self.finalize(m);
                self.skip_until_line = j + 1;
                return true;
            }
            j += 1;
        }
        false
    }

    fn try_table_conversion(&mut self, para: usize) -> bool {
        // current line must be a delimiter row; para's last line the header
        let line = &self.src[self.next_nonspace..self.le];
        let aligns = match parse_delim_row(line) {
            Some(a) => a,
            None => return false,
        };
        let last = match self.nodes[para].lines.last() {
            Some(l) => l.clone(),
            None => return false,
        };
        let header = &self.src[last.start..last.end];
        if !header.contains('|') && !line.contains('|') {
            return false;
        }
        if !header.contains('|') {
            return false;
        }
        let cells = split_row(header);
        if cells.len() != aligns.len() {
            return false;
        }
        // convert
        self.nodes[para].lines.pop();
        let parent = self.nodes[para].parent;
        let tstart = last.start;
        if self.nodes[para].lines.is_empty() {
            self.remove_node(para);
            self.tip = parent;
        } else {
            self.finalize(para);
        }
        let ncols = aligns.len();
        let t = self.new_node(Kind::Table { aligns, ncols }, parent, tstart);
        self.nodes[t].start_line = self.line_number - 1;
        self.nodes[t].lines.push(last);
        self.tip = t;
        self.offset = self.le;
        true
    }

    fn incorporate_line(&mut self) {
        let mut all_matched = true;
        let mut container = 0usize;
        self.old_tip = self.tip;
        self.offset = self.ls;
        self.column = 0;
        self.blank = false;
        self.partially_consumed_tab = false;
        self.line_number += 1;

        // 1. continuation
        loop {
            let last_child = match self.nodes[container].children.last() {
                Some(&c) if self.nodes[c].open => c,
                _ => break,
            };
            container = last_child;
            self.find_next_nonspace();
            match self.continue_block(container) {
                0 => {}
                1 => {
                    all_matched = false;
                    container = self.nodes[container].parent;
                    break;
                }
                _ => return,
            }
        }
        let _ = all_matched;
        self.all_closed = container == self.old_tip;
        self.last_matched = container;

        // metadata blocks at top level
        if self.opts.metadata && container == 0 && !matches!(self.nodes[self.tip].kind, Kind::Paragraph) {
            self.find_next_nonspace();
            if self.offset == self.ls && self.next_nonspace == self.ls && self.try_metadata() {
                return;
            }
        }

        let mut matched_leaf = !matches!(self.nodes[container].kind, Kind::Paragraph | Kind::Table { .. })
            && self.accepts_lines(container);

        // table delimiter row converting paragraph
        if !matched_leaf && self.opts.tables && matches!(self.nodes[container].kind, Kind::Paragraph) && self.all_closed {
            self.find_next_nonspace();
            if !self.indented && self.try_table_conversion(container) {
                return;
            }
        }

        // 2. new block starts
        while !matched_leaf {
            self.find_next_nonspace();
            let c = self.peek(self.next_nonspace);
            if !self.indented && !matches!(c, b'#' | b'`' | b'~' | b'*' | b'+' | b'_' | b'=' | b'<' | b'>' | b'-' | b'0'..=b'9') {
                self.advance_next_nonspace();
                break;
            }
            let r = self.try_block_starts(&mut container);
            if r == 1 {
                continue;
            } else if r == 2 {
                matched_leaf = true;
                container = self.tip;
                break;
            } else {
                self.advance_next_nonspace();
                break;
            }
        }

        // 3. add line content
        let tip_is_para = matches!(self.nodes[self.tip].kind, Kind::Paragraph);
        if !self.all_closed && !self.blank && tip_is_para {
            // lazy continuation
            self.add_line();
        } else {
            self.close_unmatched_blocks();
            if self.blank {
                if let Some(&lc) = self.nodes[container].children.last() {
                    self.nodes[lc].last_line_blank = true;
                }
            }
            let t = self.nodes[container].kind.clone();
            let last_line_blank = self.blank
                && !(matches!(t, Kind::BlockQuote)
                    || matches!(t, Kind::CodeBlock { fenced: true, .. })
                    || (matches!(t, Kind::Item { .. })
                        && self.nodes[container].children.is_empty()
                        && self.nodes[container].start_line == self.line_number));
            let mut cont = container;
            loop {
                self.nodes[cont].last_line_blank = last_line_blank;
                if cont == 0 {
                    break;
                }
                cont = self.nodes[cont].parent;
            }
            if self.accepts_lines(container) {
                match t {
                    Kind::HtmlBlock { html_type } => {
                        // add whole remaining line
                        self.add_line();
                        if (1..=5).contains(&html_type) {
                            let line = &self.src[self.offset.min(self.le)..self.le];
                            if html_block_ends(html_type, line) {
                                self.finalize(container);
                            }
                        }
                    }
                    Kind::Table { .. } => {
                        if !self.blank {
                            self.add_line();
                        }
                    }
                    Kind::CodeBlock { fenced: true, .. } | Kind::CodeBlock { .. } => {
                        if matches!(t, Kind::CodeBlock { fenced: true, .. }) && self.nodes[container].start_line == self.line_number {
                            // opening fence line: nothing to add
                        } else {
                            self.add_line();
                        }
                    }
                    Kind::Paragraph => {
                        self.add_line();
                    }
                    _ => {
                        self.add_line();
                    }
                }
            } else if self.offset < self.le && !self.blank {
                let s = self.next_nonspace;
                container = self.add_child(Kind::Paragraph, s);
                let _ = container;
                self.advance_next_nonspace();
                self.add_line();
            } else if matches!(t, Kind::Heading { .. } | Kind::ThematicBreak) {
                // nothing
            }
        }
    }
}

fn tipkind_para_tip(p: &P) -> bool {
    matches!(p.nodes[p.tip].kind, Kind::Paragraph)
}

pub(crate) fn is_thematic_break(line: &str) -> bool {
    let b = line.as_bytes();
    if b.is_empty() {
        return false;
    }
    let c = b[0];
    if !(c == b'*' || c == b'-' || c == b'_') {
        return false;
    }
    let mut n = 0;
    for &x in b {
        if x == c {
            n += 1;
        } else if x == b' ' || x == b'\t' {
        } else {
            return false;
        }
    }
    n >= 3
}

fn unescape_info(s: &str) -> String {
    inline::unescape_string(s)
}

/// Parse heading attributes `{#id .class key=val}` at end of text.
/// Returns (cut position in text, id).
fn parse_heading_attrs(text: &str) -> Option<(usize, Option<String>)> {
    if !text.ends_with('}') {
        return None;
    }
    let open = text.rfind('{')?;
    let inner = &text[open + 1..text.len() - 1];
    if inner.contains('}') {
        return None;
    }
    let mut id = None;
    for part in inner.split_whitespace() {
        if let Some(rest) = part.strip_prefix('#') {
            if !rest.is_empty() {
                id = Some(rest.to_string());
            }
        }
    }
    Some((open, id))
}

fn html_block_start(line: &str, in_paragraph: bool) -> Option<u8> {
    let lower = line.to_ascii_lowercase();
    let l = lower.as_str();
    for tag in ["script", "pre", "textarea", "style"] {
        let p = format!("<{}", tag);
        if l.starts_with(&p) {
            let rest = &l[p.len()..];
            if rest.is_empty() || rest.starts_with(|c: char| c == ' ' || c == '\t' || c == '>') {
                return Some(1);
            }
        }
    }
    if l.starts_with("<!--") {
        return Some(2);
    }
    if l.starts_with("<?") {
        return Some(3);
    }
    if l.starts_with("<![cdata[") {
        return Some(5);
    }
    if l.len() > 2 && l.starts_with("<!") && l.as_bytes()[2].is_ascii_alphabetic() {
        return Some(4);
    }
    // type 6
    {
        let rest = if let Some(r) = l.strip_prefix("</") { r } else { &l[1..] };
        let name_len = rest.bytes().take_while(|c| c.is_ascii_alphanumeric()).count();
        let name = &rest[..name_len];
        if !name.is_empty() && BLOCK_TAGS.contains(&name) {
            let after = &rest[name_len..];
            if after.is_empty()
                || after.starts_with(|c: char| c == ' ' || c == '\t' || c == '>')
                || after.starts_with("/>")
            {
                return Some(6);
            }
        }
    }
    // type 7
    if !in_paragraph {
        if let Some(n) = inline::scan_html_tag(line.as_bytes(), 0) {
            let tag = &line[..n];
            let rest = &line[n..];
            if rest.trim_matches(|c| c == ' ' || c == '\t').is_empty() && !tag.starts_with("<!") && !tag.starts_with("<?") {
                // open or closing tag only
                let lower_tag = tag.to_ascii_lowercase();
                let nm: String = lower_tag
                    .trim_start_matches("</")
                    .trim_start_matches('<')
                    .chars()
                    .take_while(|c| c.is_ascii_alphanumeric() || *c == '-')
                    .collect();
                if !["script", "style", "pre", "textarea"].contains(&nm.as_str()) || tag.starts_with("</") {
                    return Some(7);
                }
            }
        }
    }
    None
}

fn html_block_ends(t: u8, line: &str) -> bool {
    let l = line.to_ascii_lowercase();
    match t {
        1 => l.contains("</script>") || l.contains("</pre>") || l.contains("</textarea>") || l.contains("</style>"),
        2 => l.contains("-->"),
        3 => l.contains("?>"),
        4 => l.contains('>'),
        5 => l.contains("]]>"),
        _ => false,
    }
}

/// Split a table row into cell strings (raw, trimmed). Pipes escaped with
/// backslash do not split.
pub(crate) fn split_row_ranges(row: &str) -> Vec<(usize, usize)> {
    let b = row.as_bytes();
    let mut start = 0;
    let mut end = b.len();
    // trim
    while start < end && (b[start] == b' ' || b[start] == b'\t') {
        start += 1;
    }
    while end > start && (b[end - 1] == b' ' || b[end - 1] == b'\t') {
        end -= 1;
    }
    if start < end && b[start] == b'|' {
        start += 1;
    }
    if end > start && b[end - 1] == b'|' && !(end >= 2 && b[end - 2] == b'\\' && end - 1 > start) {
        end -= 1;
    }
    let mut cells = Vec::new();
    let mut cs = start;
    let mut i = start;
    while i < end {
        if b[i] == b'\\' && i + 1 < end {
            i += 2;
            continue;
        }
        if b[i] == b'|' {
            cells.push((cs, i));
            cs = i + 1;
        }
        i += 1;
    }
    cells.push((cs, end));
    // trim each
    cells
        .into_iter()
        .map(|(mut s, mut e)| {
            while s < e && (b[s] == b' ' || b[s] == b'\t') {
                s += 1;
            }
            while e > s && (b[e - 1] == b' ' || b[e - 1] == b'\t') {
                e -= 1;
            }
            (s, e)
        })
        .collect()
}

pub(crate) fn split_row(row: &str) -> Vec<String> {
    split_row_ranges(row).into_iter().map(|(s, e)| row[s..e].to_string()).collect()
}

fn parse_delim_row(line: &str) -> Option<Vec<Alignment>> {
    let t = line.trim();
    if t.is_empty() {
        return None;
    }
    let cells = split_row(t);
    let mut aligns = Vec::new();
    for c in cells {
        let c = c.trim();
        if c.is_empty() {
            return None;
        }
        let left = c.starts_with(':');
        let right = c.ends_with(':') && c.len() > 1 || (c == ":" && false);
        let inner = c.trim_start_matches(':').trim_end_matches(':');
        if inner.is_empty() || !inner.bytes().all(|x| x == b'-') {
            return None;
        }
        aligns.push(match (left, right) {
            (true, true) => Alignment::Center,
            (true, false) => Alignment::Left,
            (false, true) => Alignment::Right,
            _ => Alignment::None,
        });
    }
    Some(aligns)
}

/// Parse a link reference definition at the start of `s`.
/// Returns (bytes consumed including the trailing newline, label, def).
fn parse_ref_def(s: &str) -> Option<(usize, String, LinkDef)> {
    let b = s.as_bytes();
    if b.first() != Some(&b'[') {
        return None;
    }
    // label
    let mut i = 1;
    let mut label_end = None;
    while i < b.len() {
        match b[i] {
            b'\\' => {
                i += 2;
                continue;
            }
            b'[' => return None,
            b']' => {
                label_end = Some(i);
                break;
            }
            _ => {}
        }
        i += 1;
    }
    let le = label_end?;
    if le - 1 > 999 {
        return None;
    }
    let label = &s[1..le];
    if label.trim().is_empty() {
        return None;
    }
    i = le + 1;
    if b.get(i) != Some(&b':') {
        return None;
    }
    i += 1;
    // optional whitespace incl one newline
    let skip_ws = |mut i: usize| -> (usize, usize) {
        let mut nl = 0;
        while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
            if b[i] == b'\n' {
                nl += 1;
            }
            i += 1;
        }
        (i, nl)
    };
    let (j, nl) = skip_ws(i);
    if nl > 1 {
        return None;
    }
    i = j;
    // destination
    let (dest, di) = inline::scan_link_dest(s, i, true)?;
    if di == i && b.get(i) != Some(&b'<') {
        return None;
    }
    i = di;
    // after dest: either end of line, or whitespace then title
    let after_dest = i;
    let (j, nl2) = skip_ws(i);
    let mut title = String::new();
    let mut end_pos = None;
    if j > after_dest || j >= b.len() {
        if nl2 <= 1 && j < b.len() && (b[j] == b'"' || b[j] == b'\'' || b[j] == b'(') {
            if let Some((t, ti)) = inline::scan_link_title(s, j) {
                // rest of line must be blank
                let mut k = ti;
                while k < b.len() && (b[k] == b' ' || b[k] == b'\t') {
                    k += 1;
                }
                if k >= b.len() || b[k] == b'\n' {
                    title = t;
                    end_pos = Some(if k < b.len() { k + 1 } else { k });
                }
            }
        }
    }
    if end_pos.is_none() {
        // no title: rest of the dest line must be blank
        let mut k = after_dest;
        while k < b.len() && (b[k] == b' ' || b[k] == b'\t') {
            k += 1;
        }
        if k >= b.len() || b[k] == b'\n' {
            end_pos = Some(if k < b.len() { k + 1 } else { k });
            title.clear();
        } else {
            return None;
        }
    }
    Some((end_pos?, label.to_string(), LinkDef { dest, title }))
}

// ---------------- event generation ----------------

struct Emitter<'a, 'b> {
    p: &'b P<'a>,
    out: Vec<(Event, Range<usize>)>,
}

impl<'a, 'b> Emitter<'a, 'b> {
    fn node_end(&self, id: usize) -> usize {
        let n = &self.p.nodes[id];
        let mut e = n.start;
        if let Some(l) = n.lines.last() {
            e = e.max(l.end);
        }
        if let Some(&c) = n.children.last() {
            e = e.max(self.node_end(c));
        }
        e
    }

    fn emit_inlines(&mut self, segs: &[Seg], strip_trailing: bool) {
        let p = self.p;
        let mut buf = String::new();
        let mut map: Vec<(usize, usize)> = Vec::new();
        for (k, s) in segs.iter().enumerate() {
            if k > 0 {
                buf.push('\n');
            }
            map.push((buf.len(), s.start));
            for _ in 0..s.prefix {
                buf.push(' ');
            }
            // leading whitespace already removed for paragraphs
            map.push((buf.len(), s.start));
            buf.push_str(&p.src[s.start..s.end]);
        }
        let _ = strip_trailing;
        let evs = inline::parse_inlines(&buf, &map, &p.refs, p.opts);
        self.out.extend(evs);
    }

    fn emit(&mut self, id: usize, tight: bool) {
        let p = self.p;
        let n = &p.nodes[id];
        let start = n.start;
        let end = self.node_end(id);
        let r = start..end;
        match &n.kind {
            Kind::Document => {
                for &c in &n.children {
                    self.emit(c, false);
                }
            }
            Kind::BlockQuote => {
                self.out.push((Event::Start(Tag::BlockQuote), r.clone()));
                for &c in &n.children {
                    self.emit(c, false);
                }
                self.out.push((Event::End(Tag::BlockQuote), r));
            }
            Kind::List { ordered, start: sn, tight: t, .. } => {
                let tag = Tag::List(if *ordered { Some(*sn) } else { None });
                self.out.push((Event::Start(tag.clone()), r.clone()));
                for &c in &n.children {
                    self.emit(c, *t);
                }
                self.out.push((Event::End(tag), r));
            }
            Kind::Item { .. } => {
                self.out.push((Event::Start(Tag::Item), r.clone()));
                let mut first = true;
                for &c in &n.children {
                    let cn = &p.nodes[c];
                    if first && p.opts.tasklists {
                        if let Kind::Paragraph = cn.kind {
                            if let Some((checked, segs)) = self.task_marker(&cn.lines) {
                                let ms = cn.lines[0].start;
                                self.out.push((Event::TaskListMarker(checked), ms..ms + 3));
                                if tight {
                                    if !segs.is_empty() {
                                        self.emit_inlines(&segs, true);
                                    }
                                } else {
                                    let pr = cn.start..self.node_end(c);
                                    self.out.push((Event::Start(Tag::Paragraph), pr.clone()));
                                    if !segs.is_empty() {
                                        self.emit_inlines(&segs, true);
                                    }
                                    self.out.push((Event::End(Tag::Paragraph), pr));
                                }
                                first = false;
                                continue;
                            }
                        }
                    }
                    first = false;
                    if tight {
                        if let Kind::Paragraph = cn.kind {
                            let segs = cn.lines.clone();
                            self.emit_inlines(&segs, true);
                            continue;
                        }
                    }
                    self.emit(c, false);
                }
                self.out.push((Event::End(Tag::Item), r));
            }
            Kind::Paragraph => {
                self.out.push((Event::Start(Tag::Paragraph), r.clone()));
                let segs = n.lines.clone();
                self.emit_inlines(&segs, true);
                self.out.push((Event::End(Tag::Paragraph), r));
            }
            Kind::Heading { level, id: hid } => {
                let tag = Tag::Heading { level: *level, id: hid.clone() };
                self.out.push((Event::Start(tag.clone()), r.clone()));
                let segs = n.lines.clone();
                // strip leading/trailing whitespace of setext content
                self.emit_inlines(&segs, true);
                self.out.push((Event::End(tag), r));
            }
            Kind::ThematicBreak => {
                self.out.push((Event::Rule, r));
            }
            Kind::CodeBlock { fenced, info, .. } => {
                let kind = if *fenced { CodeKind::Fenced(info.clone()) } else { CodeKind::Indented };
                let tag = Tag::CodeBlock(kind);
                self.out.push((Event::Start(tag.clone()), r.clone()));
                for s in &n.lines {
                    let mut t = " ".repeat(s.prefix);
                    t.push_str(&p.src[s.start..s.end]);
                    t.push('\n');
                    self.out.push((Event::Text(t), s.start..s.end));
                }
                self.out.push((Event::End(tag), r));
            }
            Kind::HtmlBlock { .. } => {
                self.out.push((Event::Start(Tag::HtmlBlock), r.clone()));
                for s in &n.lines {
                    let mut t = " ".repeat(s.prefix);
                    t.push_str(&p.src[s.start..s.end]);
                    t.push('\n');
                    self.out.push((Event::Html(t), s.start..s.end));
                }
                self.out.push((Event::End(Tag::HtmlBlock), r));
            }
            Kind::Metadata => {
                self.out.push((Event::Start(Tag::MetadataBlock), r.clone()));
                let mut t = String::new();
                for s in &n.lines {
                    t.push_str(&p.src[s.start..s.end]);
                    t.push('\n');
                }
                self.out.push((Event::Text(t), r.clone()));
                self.out.push((Event::End(Tag::MetadataBlock), r));
            }
            Kind::Table { aligns, ncols } => {
                let tag = Tag::Table(aligns.clone());
                self.out.push((Event::Start(tag.clone()), r.clone()));
                for (ri, s) in n.lines.iter().enumerate() {
                    let row_src = &p.src[s.start..s.end];
                    let cells = split_row_ranges(row_src);
                    let rr = s.start..s.end;
                    if ri == 0 {
                        self.out.push((Event::Start(Tag::TableHead), rr.clone()));
                    } else {
                        self.out.push((Event::Start(Tag::TableRow), rr.clone()));
                    }
                    for ci in 0..*ncols {
                        if let Some(&(cs, ce)) = cells.get(ci) {
                            let cr = s.start + cs..s.start + ce;
                            self.out.push((Event::Start(Tag::TableCell), cr.clone()));
                            if ce > cs {
                                let seg = Seg { prefix: 0, start: s.start + cs, end: s.start + ce };
                                self.emit_cell(&seg);
                            }
                            self.out.push((Event::End(Tag::TableCell), cr));
                        } else {
                            let e = s.end;
                            self.out.push((Event::Start(Tag::TableCell), e..e));
                            self.out.push((Event::End(Tag::TableCell), e..e));
                        }
                    }
                    if ri == 0 {
                        self.out.push((Event::End(Tag::TableHead), rr));
                    } else {
                        self.out.push((Event::End(Tag::TableRow), rr));
                    }
                }
                self.out.push((Event::End(tag), r));
            }
        }
    }

    fn emit_cell(&mut self, seg: &Seg) {
        let p = self.p;
        // In table cells, "\|" becomes "|"
        let raw = &p.src[seg.start..seg.end];
        let mut buf = String::new();
        let mut map: Vec<(usize, usize)> = Vec::new();
        let rb = raw.as_bytes();
        let mut i = 0;
        map.push((0, seg.start));
        while i < rb.len() {
            if rb[i] == b'\\' && i + 1 < rb.len() && rb[i + 1] == b'|' {
                // keep escape so inline parser yields "|" as escaped text
                buf.push_str("\\|");
                i += 2;
                continue;
            }
            let ch_len = utf8_len(rb[i]);
            buf.push_str(&raw[i..i + ch_len]);
            i += ch_len;
        }
        let evs = inline::parse_inlines(&buf, &map, &p.refs, p.opts);
        self.out.extend(evs);
    }

    fn task_marker(&self, lines: &[Seg]) -> Option<(bool, Vec<Seg>)> {
        let p = self.p;
        let first = lines.first()?;
        let text = &p.src[first.start..first.end];
        let tb = text.as_bytes();
        if tb.len() < 3 || tb[0] != b'[' || tb[2] != b']' {
            return None;
        }
        let checked = match tb[1] {
            b' ' => false,
            b'x' | b'X' => true,
            _ => return None,
        };
        // must be followed by whitespace or end of line (when more lines follow or line end)
        let after = 3;
        let is_last_line_of_doc = first.end >= p.src.len();
        if tb.len() > after {
            if !(tb[after] == b' ' || tb[after] == b'\t') {
                return None;
            }
        } else if is_last_line_of_doc {
            return None;
        }
        let mut k = after;
        while k < tb.len() && (tb[k] == b' ' || tb[k] == b'\t') {
            k += 1;
        }
        let mut segs: Vec<Seg> = lines.to_vec();
        if k >= tb.len() {
            segs.remove(0);
        } else {
            segs[0].start = first.start + k;
        }
        Some((checked, segs))
    }
}

fn utf8_len(b: u8) -> usize {
    if b < 0x80 {
        1
    } else if b >> 5 == 0b110 {
        2
    } else if b >> 4 == 0b1110 {
        3
    } else {
        4
    }
}

pub(crate) fn parse_document(src: &str, opts: Options) -> Vec<(Event, Range<usize>)> {
    let lines = split_lines(src);
    let mut p = P {
        src,
        b: src.as_bytes(),
        opts,
        nodes: Vec::new(),
        tip: 0,
        old_tip: 0,
        last_matched: 0,
        all_closed: true,
        ls: 0,
        le: 0,
        offset: 0,
        column: 0,
        next_nonspace: 0,
        next_nonspace_column: 0,
        indent: 0,
        indented: false,
        blank: false,
        partially_consumed_tab: false,
        line_number: 0,
        refs: HashMap::new(),
        lines: lines.clone(),
        cur_line_idx: 0,
        skip_until_line: 0,
    };
    p.new_node(Kind::Document, 0, 0);
    p.tip = 0;
    for (idx, &(s, e)) in lines.iter().enumerate() {
        if idx < p.skip_until_line {
            p.line_number += 1;
            continue;
        }
        p.cur_line_idx = idx;
        p.ls = s;
        p.le = e;
        p.incorporate_line();
    }
    while p.tip != 0 {
        let t = p.tip;
        p.finalize(t);
    }
    p.finalize(0);
    let mut em = Emitter { p: &p, out: Vec::new() };
    em.emit(0, false);
    em.out
}
