fn is_ws_char(c: Option<char>) -> bool {
    match c {
        None => true,
        Some(c) => c.is_whitespace(),
    }
}

fn is_punct_char(c: Option<char>) -> bool {
    match c {
        None => false,
        Some(c) => {
            if c.is_ascii() {
                c.is_ascii_punctuation()
            } else {
                let u = c as u32;
                (0x2000..=0x206F).contains(&u)
                    || (0x3000..=0x303F).contains(&u)
                    || (0xFF00..=0xFF0F).contains(&u)
                    || (0xFF1A..=0xFF20).contains(&u)
                    || (0xFF3B..=0xFF40).contains(&u)
                    || (0xFF5B..=0xFF65).contains(&u)
                    || (0x00A1..=0x00BF).contains(&u) && !matches!(u, 0xAA | 0xB2 | 0xB3 | 0xB5 | 0xB9 | 0xBA | 0xBC | 0xBD | 0xBE)
                    || u == 0x00D7
                    || u == 0x00F7
                    || (0x2190..=0x23FF).contains(&u)
                    || (0x2500..=0x27BF).contains(&u)
                    || (0x2E00..=0x2E7F).contains(&u)
            }
        }
    }
}

pub(crate) fn scan_entity(b: &[u8], i: usize) -> Option<(String, usize)> {
    // b[i] == '&'
    let mut j = i + 1;
    if j < b.len() && b[j] == b'#' {
        j += 1;
        let hex = j < b.len() && (b[j] == b'x' || b[j] == b'X');
        if hex {
            j += 1;
        }
        let ds = j;
        while j < b.len() && (if hex { b[j].is_ascii_hexdigit() } else { b[j].is_ascii_digit() }) {
            j += 1;
        }
        let n = j - ds;
        if n == 0 || (hex && n > 6) || (!hex && n > 7) {
            return None;
        }
        if j >= b.len() || b[j] != b';' {
            return None;
        }
        let s = std::str::from_utf8(&b[ds..j]).ok()?;
        let v = if hex { u32::from_str_radix(s, 16).ok()? } else { s.parse::<u32>().ok()? };
        let c = if v == 0 { '\u{FFFD}' } else { char::from_u32(v).unwrap_or('\u{FFFD}') };
        return Some((c.to_string(), j + 1 - i));
    }
    let ns = j;
    while j < b.len() && b[j].is_ascii_alphanumeric() && j - ns < 40 {
        j += 1;
    }
    if j == ns || j >= b.len() || b[j] != b';' {
        return None;
    }
    let name = std::str::from_utf8(&b[ns..j]).ok()?;
    let v = entities::lookup(name)?;
    Some((v.to_string(), j + 1 - i))
}

/// Process backslash escapes and entities.
pub(crate) fn unescape_string(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::new();
    let mut i = 0;
    let mut last = 0;
    while i < b.len() {
        if b[i] == b'\\' && i + 1 < b.len() && is_ascii_punct(b[i + 1]) {
            out.push_str(&s[last..i]);
            out.push(b[i + 1] as char);
            i += 2;
            last = i;
        } else if b[i] == b'&' {
            if let Some((t, n)) = scan_entity(b, i) {
                out.push_str(&s[last..i]);
                out.push_str(&t);
                i += n;
                last = i;
            } else {
                i += 1;
            }
        } else {
            i += 1;
        }
    }
    out.push_str(&s[last..]);
    out
}

/// Scan an HTML tag (open, close, comment, PI, declaration, CDATA) at pos.
/// Returns length.
pub(crate) fn scan_html_tag(b: &[u8], pos: usize) -> Option<usize> {
    if pos >= b.len() || b[pos] != b'<' {
        return None;
    }
    let rest = &b[pos..];
    let n = rest.len();
    // comment
    if rest.starts_with(b"<!--") {
        if rest.starts_with(b"<!-->") {
            return Some(5);
        }
        if rest.starts_with(b"<!--->") {
            return Some(6);
        }
        let mut i = 4;
        while i + 2 < n + 0 && i + 3 <= n {
            if &rest[i..i + 3] == b"-->" {
                return Some(i + 3);
            }
            i += 1;
        }
        return None;
    }
    if rest.starts_with(b"<?") {
        let mut i = 2;
        while i + 1 < n {
            if &rest[i..i + 2] == b"?>" {
                return Some(i + 2);
            }
            i += 1;
        }
        return None;
    }
    if rest.starts_with(b"<![CDATA[") {
        let mut i = 9;
        while i + 2 < n {
            if &rest[i..i + 3] == b"]]>" {
                return Some(i + 3);
            }
            i += 1;
        }
        return None;
    }
    if rest.starts_with(b"<!") {
        if n > 2 && rest[2].is_ascii_alphabetic() {
            let mut i = 3;
            while i < n {
                if rest[i] == b'>' {
                    return Some(i + 1);
                }
                i += 1;
            }
        }
        return None;
    }
    let mut i = 1;
    let closing = i < n && rest[i] == b'/';
    if closing {
        i += 1;
    }
    // tag name
    if i >= n || !rest[i].is_ascii_alphabetic() {
        return None;
    }
    while i < n && (rest[i].is_ascii_alphanumeric() || rest[i] == b'-') {
        i += 1;
    }
    let ws = |c: u8| c == b' ' || c == b'\t' || c == b'\n' || c == b'\r';
    if closing {
        while i < n && ws(rest[i]) {
            i += 1;
        }
        if i < n && rest[i] == b'>' {
            return Some(i + 1);
        }
        return None;
    }
    // attributes
    loop {
        let save = i;
        let mut had_ws = false;
        while i < n && ws(rest[i]) {
            i += 1;
            had_ws = true;
        }
        if i >= n {
            return None;
        }
        if rest[i] == b'>' {
            return Some(i + 1);
        }
        if rest[i] == b'/' {
            if i + 1 < n && rest[i + 1] == b'>' {
                return Some(i + 2);
            }
            return None;
        }
        if !had_ws {
            let _ = save;
            return None;
        }
        // attribute name
        if !(rest[i].is_ascii_alphabetic() || rest[i] == b'_' || rest[i] == b':') {
            return None;
        }
        while i < n && (rest[i].is_ascii_alphanumeric() || matches!(rest[i], b'_' | b'.' | b':' | b'-')) {
            i += 1;
        }
        // optional value
        let mut j = i;
        while j < n && ws(rest[j]) {
            j += 1;
        }
        if j < n && rest[j] == b'=' {
            j += 1;
            while j < n && ws(rest[j]) {
                j += 1;
            }
            if j >= n {
                return None;
            }
            match rest[j] {
                b'"' | b'\'' => {
                    let q = rest[j];
                    j += 1;
                    while j < n && rest[j] != q {
                        j += 1;
                    }
                    if j >= n {
                        return None;
                    }
                    j += 1;
                }
                _ => {
                    let s = j;
                    while j < n && !ws(rest[j]) && !matches!(rest[j], b'"' | b'\'' | b'=' | b'<' | b'>' | b'`') {
                        j += 1;
                    }
                    if j == s {
                        return None;
                    }
                }
            }
            i = j;
        }
    }
}

fn scan_autolink(b: &[u8], pos: usize) -> Option<(usize, bool)> {
    // returns (len, is_email)
    let rest = &b[pos + 1..];
    // URI
    let mut i = 0;
    if i < rest.len() && rest[i].is_ascii_alphabetic() {
        i += 1;
        while i < rest.len() && (rest[i].is_ascii_alphanumeric() || matches!(rest[i], b'+' | b'.' | b'-')) {
            i += 1;
        }
        if (2..=32).contains(&i) && i < rest.len() && rest[i] == b':' {
            let mut j = i + 1;
            while j < rest.len() && rest[j] != b'>' && rest[j] != b'<' && rest[j] > b' ' {
                j += 1;
            }
            if j < rest.len() && rest[j] == b'>' {
                return Some((j + 2, false));
            }
        }
    }
    // email
    let mut j = 0;
    while j < rest.len() && (rest[j].is_ascii_alphanumeric() || b".!#$%&'*+/=?^_`{|}~-".contains(&rest[j])) {
        j += 1;
    }
    if j == 0 || j >= rest.len() || rest[j] != b'@' {
        return None;
    }
    j += 1;
    let mut labels = 0;
    loop {
        let ls = j;
        while j < rest.len() && (rest[j].is_ascii_alphanumeric() || rest[j] == b'-') {
            j += 1;
        }
        let ll = j - ls;
        if ll == 0 || ll > 63 || rest[ls] == b'-' || rest[j - 1] == b'-' {
            return None;
        }
        labels += 1;
        if j < rest.len() && rest[j] == b'.' {
            j += 1;
            continue;
        }
        break;
    }
    let _ = labels;
    if j < rest.len() && rest[j] == b'>' {
        return Some((j + 2, true));
    }
    None
}

/// Scan a link destination starting at i. Returns (dest, end).
pub(crate) fn scan_link_dest(s: &str, i: usize, _ref_def: bool) -> Option<(String, usize)> {
    let b = s.as_bytes();
    if i < b.len() && b[i] == b'<' {
        let mut j = i + 1;
        while j < b.len() {
            match b[j] {
                b'\\' if j + 1 < b.len() && is_ascii_punct(b[j + 1]) => j += 2,
                b'\n' | b'<' => return None,
                b'>' => return Some((unescape_string(&s[i + 1..j]), j + 1)),
                _ => j += 1,
            }
        }
        return None;
    }
    let mut j = i;
    let mut depth = 0i32;
    while j < b.len() {
        let c = b[j];
        if c == b'\\' && j + 1 < b.len() && is_ascii_punct(b[j + 1]) {
            j += 2;
            continue;
        }
        if c == b'(' {
            depth += 1;
            if depth > 32 {
                return None;
            }
        } else if c == b')' {
            if depth == 0 {
                break;
            }
            depth -= 1;
        } else if c <= b' ' {
            break;
        }
        j += 1;
    }
    if depth != 0 {
        return None;
    }
    Some((unescape_string(&s[i..j]), j))
}

pub(crate) fn scan_link_title(s: &str, i: usize) -> Option<(String, usize)> {
    let b = s.as_bytes();
    if i >= b.len() {
        return None;
    }
    let close = match b[i] {
        b'"' => b'"',
        b'\'' => b'\'',
        b'(' => b')',
        _ => return None,
    };
    let mut j = i + 1;
    let mut last_nl = false;
    while j < b.len() {
        let c = b[j];
        if c == b'\\' && j + 1 < b.len() && is_ascii_punct(b[j + 1]) {
            j += 2;
            last_nl = false;
            continue;
        }
        if c == close {
            return Some((unescape_string(&s[i + 1..j]), j + 1));
        }
        if close == b')' && c == b'(' {
            return None;
        }
        if c == b'\n' {
            // blank line not allowed
            if last_nl {
                return None;
            }
            last_nl = true;
        } else if c != b' ' && c != b'\t' {
            last_nl = false;
        }
        j += 1;
    }
    None
}

impl<'a> IP<'a> {
    fn push(&mut self, kind: IK, start: usize, end: usize) -> usize {
        let id = self.items.len();
        self.items.push(Item { kind, start, end, prev: self.tail, next: NIL });
        if self.tail != NIL {
            self.items[self.tail].next = id;
        } else {
            self.head = id;
        }
        self.tail = id;
        id
    }

    fn append_text(&mut self, start: usize, end: usize) {
        if end <= start {
            return;
        }
        if self.tail != NIL {
            let t = self.tail;
            if matches!(self.items[t].kind, IK::Text) && self.items[t].end == start {
                self.items[t].end = end;
                return;
            }
        }
        self.push(IK::Text, start, end);
    }

    fn insert_after(&mut self, at: usize, kind: IK, start: usize, end: usize) -> usize {
        let id = self.items.len();
        let next = self.items[at].next;
        self.items.push(Item { kind, start, end, prev: at, next });
        self.items[at].next = id;
        if next != NIL {
            self.items[next].prev = id;
        } else {
            self.tail = id;
        }
        id
    }

    fn insert_before(&mut self, at: usize, kind: IK, start: usize, end: usize) -> usize {
        let id = self.items.len();
        let prev = self.items[at].prev;
        self.items.push(Item { kind, start, end, prev, next: at });
        self.items[at].prev = id;
        if prev != NIL {
            self.items[prev].next = id;
        } else {
            self.head = id;
        }
        id
    }

    fn unlink(&mut self, id: usize) {
        let prev = self.items[id].prev;
        let next = self.items[id].next;
        if prev != NIL {
            self.items[prev].next = next;
        } else {
            self.head = next;
        }
        if next != NIL {
            self.items[next].prev = prev;
        } else {
            self.tail = prev;
        }
        self.items[id].kind = IK::Dead;
    }

    fn char_before(&self, pos: usize) -> Option<char> {
        if pos == 0 {
            None
        } else {
            self.buf[..pos].chars().next_back()
        }
    }

    fn char_at(&self, pos: usize) -> Option<char> {
        self.buf[pos..].chars().next()
    }

    fn first_pass(&mut self) {
        let b = self.b;
        let len = b.len();
        let mut i = 0;
        let mut ts = 0;
        while i < len {
            let c = b[i];
            match c {
                b'\n' => {
                    let mut te = i;
                    while te > ts && (b[te - 1] == b' ' || b[te - 1] == b'\t') {
                        te -= 1;
                    }
                    let spaces = b[te..i].iter().filter(|&&x| x == b' ').count();
                    self.append_text(ts, te);
                    if spaces >= 2 {
                        self.push(IK::HardBreak, te, i + 1);
                    } else {
                        self.push(IK::SoftBreak, i, i + 1);
                    }
                    i += 1;
                    while i < len && (b[i] == b' ' || b[i] == b'\t') {
                        i += 1;
                    }
                    ts = i;
                }
                b'\\' => {
                    if i + 1 < len && b[i + 1] == b'\n' {
                        self.append_text(ts, i);
                        self.push(IK::HardBreak, i, i + 2);
                        i += 2;
                        while i < len && (b[i] == b' ' || b[i] == b'\t') {
                            i += 1;
                        }
                        ts = i;
                    } else if i + 1 < len && is_ascii_punct(b[i + 1]) {
                        self.append_text(ts, i);
                        ts = i + 1;
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                b'*' | b'_' | b'~' => {
                    let mut n = 1;
                    while i + n < len && b[i + n] == c {
                        n += 1;
                    }
                    if c == b'~' && !self.opts.strikethrough {
                        i += n;
                        continue;
                    }
                    let before = self.char_before(i);
                    let after = if i + n < len { self.char_at(i + n) } else { None };
                    let ws_after = is_ws_char(after);
                    let ws_before = is_ws_char(before);
                    let p_after = is_punct_char(after);
                    let p_before = is_punct_char(before);
                    let left = !ws_after && (!p_after || ws_before || p_before);
                    let right = !ws_before && (!p_before || ws_after || p_after);
                    let (can_open, can_close) = if c == b'_' {
                        (left && (!right || p_before), right && (!left || p_after))
                    } else {
                        (left, right)
                    };
                    let valid = c != b'~' || n <= 2;
                    if (can_open || can_close) && valid {
                        self.append_text(ts, i);
                        self.push(IK::Delim { ch: c, orig: n, can_open, can_close, active: true }, i, i + n);
                        ts = i + n;
                    }
                    i += n;
                }
                b'`' => {
                    let mut n = 1;
                    while i + n < len && b[i + n] == b'`' {
                        n += 1;
                    }
                    self.append_text(ts, i);
                    self.push(IK::Backticks, i, i + n);
                    i += n;
                    ts = i;
                }
                b'!' if i + 1 < len && b[i + 1] == b'[' => {
                    self.append_text(ts, i);
                    self.push(IK::ImageOpen, i, i + 2);
                    i += 2;
                    ts = i;
                }
                b'[' => {
                    self.append_text(ts, i);
                    self.push(IK::LinkOpen, i, i + 1);
                    i += 1;
                    ts = i;
                }
                b']' => {
                    self.append_text(ts, i);
                    self.push(IK::LinkClose, i, i + 1);
                    i += 1;
                    ts = i;
                }
                b'<' => {
                    self.append_text(ts, i);
                    self.push(IK::Lt, i, i + 1);
                    i += 1;
                    ts = i;
                }
                b'&' => {
                    if let Some((t, n)) = scan_entity(b, i) {
                        self.append_text(ts, i);
                        self.push(IK::Synth(t), i, i + n);
                        i += n;
                        ts = i;
                    } else {
                        i += 1;
                    }
                }
                _ => i += 1,
            }
        }
        // trailing whitespace at end
        let mut te = len;
        while te > ts && (b[te - 1] == b' ' || b[te - 1] == b'\t') {
            te -= 1;
        }
        self.append_text(ts, te);
    }

    /// Remove/truncate items covering [from, to) starting from item `after`'s next.
    fn consume_range(&mut self, after: usize, to: usize) {
        let mut cur = self.items[after].next;
        while cur != NIL {
            let it = &self.items[cur];
            if it.start >= to {
                break;
            }
            let next = it.next;
            if it.end <= to {
                self.unlink(cur);
            } else {
                // straddles
                match self.items[cur].kind {
                    IK::Text => {
                        self.items[cur].start = to;
                    }
                    _ => {
                        self.unlink(cur);
                    }
                }
                break;
            }
            cur = next;
        }
    }

    fn to_text(&mut self, id: usize) {
        self.items[id].kind = IK::Text;
    }

    fn handle_code(&mut self, id: usize) {
        let s = self.items[id].start;
        let e = self.items[id].end;
        let n = e - s;
        let b = self.b;
        // search for closing run of exactly n
        let mut j = e;
        while j < b.len() {
            if b[j] == b'`' {
                let rs = j;
                while j < b.len() && b[j] == b'`' {
                    j += 1;
                }
                if j - rs == n {
                    // found
                    let raw = &self.buf[e..rs];
                    let mut content: String = raw.chars().map(|c| if c == '\n' { ' ' } else { c }).collect();
                    if content.len() >= 2
                        && content.starts_with(' ')
                        && content.ends_with(' ')
                        && !content.bytes().all(|x| x == b' ')
                    {
                        content = content[1..content.len() - 1].to_string();
                    }
                    self.items[id].kind = IK::Code(content);
                    self.items[id].end = j;
                    self.consume_range(id, j);
                    return;
                }
            } else {
                j += 1;
            }
        }
        self.to_text(id);
    }

    fn handle_lt(&mut self, id: usize) {
        let s = self.items[id].start;
        let b = self.b;
        if let Some((n, email)) = scan_autolink(b, s) {
            let url = self.buf[s + 1..s + n - 1].to_string();
            let tag = Tag::Link {
                dest: url.clone(),
                title: String::new(),
                kind: if email { LinkKind::Email } else { LinkKind::Autolink },
            };
            self.items[id].kind = IK::Start(tag.clone());
            self.items[id].end = s + 1;
            let t = self.insert_after(id, IK::Synth(url), s + 1, s + n - 1);
            let e = self.insert_after(t, IK::End(tag), s + n - 1, s + n);
            let _ = e;
            // consume items after e up to s+n
            self.consume_range(e, s + n);
            return;
        }
        if let Some(n) = scan_html_tag(b, s) {
            let html = self.buf[s..s + n].to_string();
            self.items[id].kind = IK::Html(html);
            self.items[id].end = s + n;
            self.consume_range(id, s + n);
            return;
        }
        self.to_text(id);
    }

    fn raw_between(&self, a: usize, b: usize) -> &str {
        &self.buf[a..b]
    }

    /// Try to parse link suffix after the close bracket at position `p` (index of ']').
    /// Returns (dest, title, end position, is_reference)
    fn parse_link_suffix(&self, open_end: usize, p: usize) -> Option<(String, String, usize, LinkKind)> {
        let b = self.b;
        let after = p + 1;
        if after < b.len() && b[after] == b'(' {
            // inline link
            let mut i = after + 1;
            let skip = |mut i: usize| {
                let mut nl = 0;
                while i < b.len() && (b[i] == b' ' || b[i] == b'\t' || b[i] == b'\n') {
                    if b[i] == b'\n' {
                        nl += 1;
                    }
                    i += 1;
                }
                (i, nl)
            };
            let (j, _) = skip(i);
            i = j;
            if let Some((dest, di)) = scan_link_dest(self.buf, i, false) {
                let (j, _) = skip(di);
                let mut title = String::new();
                let mut k = j;
                if j > di && j < b.len() && (b[j] == b'"' || b[j] == b'\'' || b[j] == b'(') {
                    if let Some((t, ti)) = scan_link_title(self.buf, j) {
                        title = t;
                        let (k2, _) = skip(ti);
                        k = k2;
                    }
                }
                if k < b.len() && b[k] == b')' {
                    return Some((dest, title, k + 1, LinkKind::Inline));
                }
            }
            // fall through to reference forms
        }
        // reference link
        let text_label = self.raw_between(open_end, p);
        if after < b.len() && b[after] == b'[' {
            // find closing ]
            let mut j = after + 1;
            let mut ok = false;
            while j < b.len() {
                match b[j] {
                    b'\\' if j + 1 < b.len() => j += 2,
                    b'[' => break,
                    b']' => {
                        ok = true;
                        break;
                    }
                    _ => j += 1,
                }
            }
            if ok {
                let label = &self.buf[after + 1..j];
                if label.trim().is_empty() {
                    // collapsed
                    let key = normalize_label(text_label);
                    if let Some(d) = self.refs.get(&key) {
                        return Some((d.dest.clone(), d.title.clone(), j + 1, LinkKind::Reference));
                    }
                    return None;
                } else {
                    let key = normalize_label(label);
                    if let Some(d) = self.refs.get(&key) {
                        return Some((d.dest.clone(), d.title.clone(), j + 1, LinkKind::Reference));
                    }
                    return None;
                }
            }
        }
        // shortcut
        let key = normalize_label(text_label);
        if key.is_empty() {
            return None;
        }
        if let Some(d) = self.refs.get(&key) {
            return Some((d.dest.clone(), d.title.clone(), p + 1, LinkKind::Reference));
        }
        None
    }

    fn second_pass(&mut self) {
        let mut brackets: Vec<(usize, bool)> = Vec::new(); // (item id, active)
        let mut cur = self.head;
        while cur != NIL {
            let next = self.items[cur].next;
            match self.items[cur].kind.clone() {
                IK::Backticks => {
                    self.handle_code(cur);
                }
                IK::Lt => {
                    self.handle_lt(cur);
                }
                IK::LinkOpen | IK::ImageOpen => {
                    brackets.push((cur, true));
                }
                IK::LinkClose => {
                    if let Some(&(op, active)) = brackets.last() {
                        if !active {
                            brackets.pop();
                            self.to_text(cur);
                        } else {
                            let is_image = matches!(self.items[op].kind, IK::ImageOpen);
                            let open_end = self.items[op].end;
                            let p = self.items[cur].start;
                            match self.parse_link_suffix(open_end, p) {
                                Some((dest, title, end, kind)) => {
                                    brackets.pop();
                                    let tag = if is_image {
                                        Tag::Image { dest, title }
                                    } else {
                                        Tag::Link { dest, title, kind }
                                    };
                                    // process emphasis inside
                                    self.process_emphasis(op, cur);
                                    self.items[op].kind = IK::Start(tag.clone());
                                    self.items[cur].kind = IK::End(tag);
                                    self.items[cur].end = end;
                                    self.consume_range(cur, end);
                                    if !is_image {
                                        for br in brackets.iter_mut() {
                                            if matches!(self.items[br.0].kind, IK::LinkOpen) {
                                                br.1 = false;
                                            }
                                        }
                                    }
                                    let nn = self.items[cur].next;
                                    cur = nn;
                                    continue;
                                }
                                None => {
                                    brackets.pop();
                                    self.to_text(op);
                                    self.to_text(cur);
                                }
                            }
                        }
                    } else {
                        self.to_text(cur);
                    }
                }
                _ => {}
            }
            // next may have been changed by consume_range
            let nn = if self.items[cur].kind.is_dead() { next } else { self.items[cur].next };
            cur = nn;
        }
        for (op, _) in brackets {
            if matches!(self.items[op].kind, IK::LinkOpen | IK::ImageOpen) {
                self.to_text(op);
            }
        }
        self.process_emphasis(NIL, NIL);
        // remaining delims -> text
        let mut cur = self.head;
        while cur != NIL {
            let next = self.items[cur].next;
            if let IK::Delim { .. } = self.items[cur].kind {
                if self.items[cur].end > self.items[cur].start {
                    self.to_text(cur);
                } else {
                    self.unlink(cur);
                }
            }
            cur = next;
        }
    }

    /// Process emphasis among delimiters strictly between `lo` and `hi`
    /// (item ids, NIL meaning list start/end).
    fn process_emphasis(&mut self, lo: usize, hi: usize) {
        // collect delimiters
        let mut delims: Vec<usize> = Vec::new();
        let mut cur = if lo == NIL { self.head } else { self.items[lo].next };
        while cur != NIL && cur != hi {
            if let IK::Delim { active: true, .. } = self.items[cur].kind {
                delims.push(cur);
            }
            cur = self.items[cur].next;
        }
        if delims.is_empty() {
            return;
        }
        // openers_bottom indexed by (ch, can_open as closer, orig%3)
        let mut bottom: HashMap<(u8, bool, usize), isize> = HashMap::new();
        let mut ci = 0usize;
        while ci < delims.len() {
            let closer = delims[ci];
            let (cch, corig, c_open, c_close) = match self.items[closer].kind {
                IK::Delim { ch, orig, can_open, can_close, active: true } => (ch, orig, can_open, can_close),
                _ => {
                    ci += 1;
                    continue;
                }
            };
            if !c_close || self.items[closer].end <= self.items[closer].start {
                ci += 1;
                continue;
            }
            let key = (cch, c_open, corig % 3);
            let lim = *bottom.get(&key).unwrap_or(&-1);
            let mut found: Option<usize> = None;
            let mut oi = ci as isize - 1;
            while oi > lim {
                let opener = delims[oi as usize];
                if let IK::Delim { ch, orig, can_open, can_close, active: true } = self.items[opener].kind {
                    if ch == cch && can_open && self.items[opener].end > self.items[opener].start {
                        let ocount = self.items[opener].end - self.items[opener].start;
                        let ccount = self.items[closer].end - self.items[closer].start;
                        let mut ok = true;
                        if cch == b'~' {
                            ok = ocount == ccount;
                        } else if (can_close || c_open) && (orig + corig) % 3 == 0 && !(orig % 3 == 0 && corig % 3 == 0) {
                            ok = false;
                        }
                        if ok {
                            found = Some(oi as usize);
                            break;
                        }
                    }
                }
                oi -= 1;
            }
            match found {
                Some(oidx) => {
                    let opener = delims[oidx];
                    let ocount = self.items[opener].end - self.items[opener].start;
                    let ccount = self.items[closer].end - self.items[closer].start;
                    let (used, tag) = if cch == b'~' {
                        (ccount, Tag::Strikethrough)
                    } else if ocount >= 2 && ccount >= 2 {
                        (2, Tag::Strong)
                    } else {
                        (1, Tag::Emphasis)
                    };
                    // deactivate delimiters between
                    for &d in &delims[oidx + 1..ci] {
                        if let IK::Delim { ch, orig, can_open, can_close, .. } = self.items[d].kind {
                            self.items[d].kind = IK::Delim { ch, orig, can_open, can_close, active: false };
                        }
                    }
                    let oe = self.items[opener].end;
                    self.items[opener].end = oe - used;
                    self.insert_after(opener, IK::Start(tag.clone()), oe - used, oe);
                    let cs = self.items[closer].start;
                    self.items[closer].start = cs + used;
                    self.insert_before(closer, IK::End(tag), cs, cs + used);
                    if self.items[opener].end == self.items[opener].start {
                        self.unlink(opener);
                    }
                    if self.items[closer].end == self.items[closer].start {
                        self.unlink(closer);
                        ci += 1;
                    }
                }
                None => {
                    bottom.insert(key, ci as isize - 1);
                    if !c_open {
                        if let IK::Delim { ch, orig, can_open, can_close, .. } = self.items[closer].kind {
                            self.items[closer].kind = IK::Delim { ch, orig, can_open, can_close, active: false };
                        }
                    }
                    ci += 1;
                }
            }
        }
        // inactive delims within range become text later (they remain Delim with active=false);
        // to prevent outer processing, convert them now when lo != NIL
        if lo != NIL {
            for d in delims {
                if let IK::Delim { .. } = self.items[d].kind {
                    if self.items[d].end > self.items[d].start {
                        self.to_text(d);
                    } else {
                        self.unlink(d);
                    }
                }
            }
        }
    }

    fn events(&self, map: &[(usize, usize)]) -> Vec<(Event, Range<usize>)> {
        let to_src = |pos: usize| -> usize {
            let mut best = (0usize, 0usize);
            for &(bp, sp) in map {
                if bp <= pos {
                    best = (bp, sp);
                } else {
                    break;
                }
            }
            best.1 + (pos - best.0)
        };
        let mut out = Vec::new();
        let mut cur = self.head;
        while cur != NIL {
            let it = &self.items[cur];
            let r = to_src(it.start)..to_src(it.end);
            let ev = match &it.kind {
                IK::Text | IK::Backticks | IK::LinkOpen | IK::ImageOpen | IK::LinkClose | IK::Lt => {
                    if it.end > it.start {
                        Some(Event::Text(self.buf[it.start..it.end].to_string()))
                    } else {
                        None
                    }
                }
                IK::Delim { .. } => {
                    if it.end > it.start {
                        Some(Event::Text(self.buf[it.start..it.end].to_string()))
                    } else {
                        None
                    }
                }
                IK::Synth(s) => Some(Event::Text(s.clone())),
                IK::SoftBreak => Some(Event::SoftBreak),
                IK::HardBreak => Some(Event::HardBreak),
                IK::Code(c) => Some(Event::Code(c.clone())),
                IK::Html(h) => Some(Event::InlineHtml(h.clone())),
                IK::Start(t) => Some(Event::Start(t.clone())),
                IK::End(t) => Some(Event::End(t.clone())),
                IK::Dead => None,
            };
            if let Some(e) = ev {
                out.push((e, r));
            }
            cur = it.next;
        }
        out
    }
}

impl IK {
    fn is_dead(&self) -> bool {
        matches!(self, IK::Dead)
    }
}

pub(crate) fn parse_inlines(
    buf: &str,
    map: &[(usize, usize)],
    refs: &HashMap<String, LinkDef>,
    opts: Options,
) -> Vec<(Event, Range<usize>)> {
    let mut ip = IP { buf, b: buf.as_bytes(), items: Vec::new(), head: NIL, tail: NIL, refs, opts };
    ip.first_pass();
    ip.second_pass();
    ip.events(map)
}
