use super::block::LinkDef;
use super::*;
use std::collections::HashMap;

#[derive(Clone, Debug)]
enum IK {
    Text,
    Synth(String),
    Delim { ch: u8, orig: usize, can_open: bool, can_close: bool, active: bool },
    Backticks,
    LinkOpen,
    ImageOpen,
    LinkClose,
    Lt,
    SoftBreak,
