/// Wrap link destinations containing spaces in angle brackets:
/// `[text](a b)` -> `[text](<a b>)`.
pub fn preprocess_links(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::with_capacity(s.len() + 16);
    let mut i = 0;
    let mut last = 0;
    while i < b.len() {
        if b[i] == b'[' {
            // text: [^\]]+
            let mut j = i + 1;
            while j < b.len() && b[j] != b']' {
                j += 1;
            }
            if j < b.len() && j > i + 1 && j + 1 < b.len() && b[j + 1] == b'(' {
                // url: [^)<>]+ ' ' [^)<>]*  then ')'
                let us = j + 2;
                let mut k = us;
                while k < b.len() && b[k] != b')' && b[k] != b'<' && b[k] != b'>' {
                    k += 1;
                }
                if k < b.len() && b[k] == b')' {
                    let url = &s[us..k];
                    // need a space at index >= 1
                    let has_space = url.len() >= 2 && url[1..].contains(' ');
                    if has_space {
                        out.push_str(&s[last..us]);
                        out.push('<');
                        out.push_str(url);
                        out.push('>');
                        out.push(')');
                        i = k + 1;
                        last = i;
                        continue;
                    }
                }
            }
            // regex would retry at next '[' inside text; text cannot contain ']'
            // so the next candidate '[' is after i
            i += 1;
            continue;
        }
        i += 1;
    }
    out.push_str(&s[last..]);
    out
}

struct ItemState {
    checked: Option<bool>,
    blocks: Vec<Block>,
    saved_inline: Vec<Inline>,
}

struct TableState {
    aligns: Vec<String>,
    headers: Vec<String>,
    rows: Vec<Vec<String>>,
    row: Vec<String>,
    in_head: bool,
}

struct B {
    line: usize,
    blocks: Vec<Block>,
    text: String,
    inline: Vec<Inline>,
    in_paragraph: bool,
    heading: Option<u8>,
    in_code: bool,
    code_lang: Option<String>,
    code_buf: String,
    list_depth: usize,
    list_ordered: bool,
    items: Vec<ListItem>,
    item: Option<ItemState>,
    item_depth: usize,
    in_bq: bool,
    bq_text: String,
    table: Option<TableState>,
    em: usize,
    strong: usize,
    strike: usize,
    in_link: bool,
    link_text: String,
    in_image: bool,
}

impl B {
    fn styled(&self, t: &str) -> Inline {
        if self.strong > 0 {
            Inline::Strong(t.to_string())
        } else if self.em > 0 {
            Inline::Emphasis(t.to_string())
        } else if self.strike > 0 {
            Inline::Strikethrough(t.to_string())
        } else {
            Inline::Text(t.to_string())
        }
    }

    fn in_item(&self) -> bool {
        self.item.is_some()
    }

    fn event(&mut self, ev: Event) {
        match ev {
            Event::Start(tag) => self.start(tag),
            Event::End(tag) => self.end(tag),
            Event::Text(t) => {
                if self.in_code {
                    self.code_buf.push_str(&t);
                } else if self.in_bq {
                    self.bq_text.push_str(&t);
                } else if self.in_link {
                    self.link_text.push_str(&t);
                } else if self.in_image {
                    self.text.push_str(&t);
                } else {
                    self.text.push_str(&t);
                    let s = self.styled(&t);
                    self.inline.push(s);
                }
            }
            Event::Code(c) => {
                self.text.push_str(&c);
                self.inline.push(Inline::Code(c));
            }
            Event::SoftBreak => {
                if self.in_paragraph {
                    self.text.push(' ');
                    self.inline.push(Inline::Text(" ".into()));
                }
            }
            Event::HardBreak => {
                if self.in_paragraph {
                    self.text.push('\n');
                    self.inline.push(Inline::Text("\n".into()));
                }
            }
            Event::Rule => self.blocks.push(Block::HorizontalRule),
            Event::TaskListMarker(c) => {
                if self.item_depth <= 1 {
                    if let Some(it) = self.item.as_mut() {
                        it.checked = Some(c);
                    }
                } else {
                    self.text.push_str(if c { "[x] " } else { "[ ] " });
                }
            }
            Event::Html(_) | Event::InlineHtml(_) => {}
        }
    }

    fn start(&mut self, tag: Tag) {
        match tag {
            Tag::Paragraph => self.in_paragraph = true,
            Tag::Heading { level, .. } => self.heading = Some(level),
            Tag::CodeBlock(kind) => {
                self.in_code = true;
                self.code_buf.clear();
                self.code_lang = match kind {
                    md::CodeKind::Fenced(info) => {
                        if info.is_empty() {
                            None
                        } else {
                            Some(info)
                        }
                    }
                    md::CodeKind::Indented => None,
                };
            }
            Tag::List(start) => {
                self.list_depth += 1;
                if self.list_depth == 1 {
                    self.list_ordered = start.is_some();
                    self.items.clear();
                }
            }
            Tag::Item => {
                self.item_depth += 1;
                if self.item_depth == 1 {
                    self.item = Some(ItemState { checked: None, blocks: Vec::new(), saved_inline: Vec::new() });
                    self.text.clear();
                    self.inline.clear();
                } else {
                    if !self.text.is_empty() {
                        self.text.push('\n');
                    }
                    let ind = "  ".repeat(self.item_depth - 1);
                    self.text.push_str(&ind);
                }
            }
            Tag::BlockQuote => {
                self.in_bq = true;
                self.bq_text.clear();
            }
            Tag::Table(aligns) => {
                let a = aligns
                    .iter()
                    .map(|a| match a {
                        md::Alignment::None => "none",
                        md::Alignment::Left => "left",
                        md::Alignment::Center => "center",
                        md::Alignment::Right => "right",
                    })
                    .map(String::from)
                    .collect();
                self.table = Some(TableState { aligns: a, headers: vec![], rows: vec![], row: vec![], in_head: false });
            }
            Tag::TableHead => {
                if let Some(t) = self.table.as_mut() {
                    t.in_head = true;
                    t.row.clear();
                }
            }
            Tag::TableRow => {
                if let Some(t) = self.table.as_mut() {
                    t.row.clear();
                }
            }
            Tag::TableCell => {
                self.text.clear();
            }
            Tag::Emphasis => self.em += 1,
            Tag::Strong => self.strong += 1,
            Tag::Strikethrough => self.strike += 1,
            Tag::Link { .. } => {
                self.in_link = true;
                self.link_text.clear();
            }
            Tag::Image { .. } => {
                if !self.in_link {
                    self.in_image = true;
                    self.text.clear();
                }
            }
            Tag::HtmlBlock | Tag::MetadataBlock => {}
        }
    }

    fn end(&mut self, tag: Tag) {
        match tag {
            Tag::Paragraph => {
                self.in_paragraph = false;
                let text = std::mem::take(&mut self.text);
                let inline = std::mem::take(&mut self.inline);
                if let Some(it) = self.item.as_mut() {
                    it.blocks.push(Block::Paragraph { content: text, inline: inline.clone() });
                    it.saved_inline.extend(inline);
                } else if !text.is_empty() {
                    self.blocks.push(Block::Paragraph { content: text, inline });
                }
            }
            Tag::Heading { level, .. } => {
                self.heading = None;
                let text = std::mem::take(&mut self.text);
                let inline = std::mem::take(&mut self.inline);
                if !text.is_empty() {
                    self.blocks.push(Block::Heading { level, content: text, inline });
                }
            }
            Tag::CodeBlock(_) => {
                self.in_code = false;
                if !self.code_buf.is_empty() {
                    let b = Block::Code {
                        language: self.code_lang.take(),
                        content: self.code_buf.trim_end().to_string(),
                        line: self.line,
                    };
                    if let Some(it) = self.item.as_mut() {
                        it.blocks.push(b);
                    } else {
                        self.blocks.push(b);
                    }
                }
                self.code_buf.clear();
            }
            Tag::List(_) => {
                if self.list_depth == 1 {
                    let items = std::mem::take(&mut self.items);
                    self.blocks.push(Block::List { ordered: self.list_ordered, items });
                }
                self.list_depth = self.list_depth.saturating_sub(1);
            }
            Tag::Item => {
                if self.item_depth == 1 {
                    if let Some(mut it) = self.item.take() {
                        let mut content = std::mem::take(&mut self.text);
                        if content.is_empty() {
                            if let Some(Block::Paragraph { .. }) = it.blocks.first() {
                                if let Block::Paragraph { content: c, .. } = it.blocks.remove(0) {
                                    content = c;
                                }
                            }
                        }
                        let mut inline = std::mem::take(&mut self.inline);
                        inline.extend(it.saved_inline.drain(..));
                        self.items.push(ListItem { checked: it.checked, content, inline, blocks: it.blocks });
                    }
                }
                self.item_depth = self.item_depth.saturating_sub(1);
            }
            Tag::BlockQuote => {
                if self.in_bq {
                    self.in_bq = false;
                    let t = std::mem::take(&mut self.bq_text);
                    if !t.is_empty() {
                        let blocks = build_blocks_raw(&t, self.line);
                        self.blocks.push(Block::Blockquote { content: t, blocks });
                    }
                }
            }
            Tag::TableCell => {
                let t = std::mem::take(&mut self.text);
                if let Some(tb) = self.table.as_mut() {
                    tb.row.push(t.trim().to_string());
                }
                self.inline.clear();
            }
            Tag::TableHead => {
                if let Some(t) = self.table.as_mut() {
                    t.headers = std::mem::take(&mut t.row);
                    t.in_head = false;
                }
            }
            Tag::TableRow => {
                if let Some(t) = self.table.as_mut() {
                    let r = std::mem::take(&mut t.row);
                    t.rows.push(r);
                }
            }
            Tag::Table(_) => {
                if let Some(t) = self.table.take() {
                    self.blocks.push(Block::Table { headers: t.headers, alignments: t.aligns, rows: t.rows });
                }
                self.inline.clear();
            }
            Tag::Emphasis => self.em = self.em.saturating_sub(1),
            Tag::Strong => self.strong = self.strong.saturating_sub(1),
            Tag::Strikethrough => self.strike = self.strike.saturating_sub(1),
            Tag::Link { dest, .. } => {
                self.in_link = false;
                let lt = std::mem::take(&mut self.link_text);
                let line_offset = if self.in_item() { Some(self.text.matches('\n').count()) } else { None };
                self.inline.push(Inline::Link { text: lt.clone(), url: dest.clone(), line_offset });
                self.text.push_str(&format!("[{}]({})", lt, dest));
            }
            Tag::Image { dest, .. } => {
                if self.in_link {
                    return;
                }
                self.in_image = false;
                let alt = std::mem::take(&mut self.text);
                if self.in_paragraph {
                    self.inline.push(Inline::Image { alt: alt.clone(), src: dest.clone() });
                    self.text = format!("![{}]({})", alt, dest);
                } else {
                    self.blocks.push(Block::Image { alt, src: dest });
                }
            }
            Tag::HtmlBlock | Tag::MetadataBlock => {}
        }
    }
}

/// Build blocks from (already preprocessed) markdown text, handling
/// `<details>` sections textually.
pub fn build_blocks_raw(text: &str, line: usize) -> Vec<Block> {
    if let Some(start) = text.find("<details") {
        if let Some(rel_end) = text[start..].find("</details>") {
            let end = start + rel_end;
            let mut out = build_events(&text[..start], line);
            let inner = &text[start..end];
            // summary
            let mut summary = String::new();
            let body_start;
            if let Some(ss) = inner.find("<summary>") {
                if let Some(se_rel) = inner[ss..].find("</summary>") {
                    summary = inner[ss + 9..ss + se_rel].to_string();
                    body_start = ss + se_rel + 10;
                } else {
                    body_start = inner.find('>').map(|p| p + 1).unwrap_or(inner.len());
                }
            } else {
                body_start = inner.find('>').map(|p| p + 1).unwrap_or(inner.len());
            }
            let content = inner[body_start.min(inner.len())..].trim().to_string();
            let blocks = build_blocks_raw(&content, line);
            out.push(Block::Details { summary: summary.trim().to_string(), content, blocks });
            out.extend(build_blocks_raw(&text[end + "</details>".len()..], line));
            return out;
        }
    }
    build_events(text, line)
}

fn build_events(text: &str, line: usize) -> Vec<Block> {
    let evs = md::parse(text, md::Options::gfm());
    let mut b = B {
        line,
        blocks: Vec::new(),
        text: String::new(),
        inline: Vec::new(),
        in_paragraph: false,
        heading: None,
        in_code: false,
        code_lang: None,
        code_buf: String::new(),
        list_depth: 0,
        list_ordered: false,
        items: Vec::new(),
        item: None,
        item_depth: 0,
        in_bq: false,
        bq_text: String::new(),
        table: None,
        em: 0,
        strong: 0,
        strike: 0,
        in_link: false,
        link_text: String::new(),
        in_image: false,
    };
    for (e, _) in evs {
        b.event(e);
    }
    b.blocks
}

/// Build blocks for a raw section content (applies link preprocessing).
pub fn build_blocks(raw: &str, line: usize) -> Vec<Block> {
    let pre = preprocess_links(raw);
    build_blocks_raw(&pre, line)
}

pub fn inline_json(i: &Inline) -> Value {
    match i {
        Inline::Text(v) => json!({"type": "text", "value": v}),
        Inline::Emphasis(v) => json!({"type": "emphasis", "value": v}),
        Inline::Strong(v) => json!({"type": "strong", "value": v}),
        Inline::Strikethrough(v) => json!({"type": "strikethrough", "value": v}),
        Inline::Code(v) => json!({"type": "code", "value": v}),
        Inline::Link { text, url, line_offset } => {
            let mut m = Map::new();
            m.insert("type".into(), "link".into());
            m.insert("text".into(), text.clone().into());
            m.insert("url".into(), url.clone().into());
            m.insert("title".into(), Value::Null);
            if let Some(lo) = line_offset {
                m.insert("line_offset".into(), (*lo as u64).into());
            }
            Value::Object(m)
        }
        Inline::Image { alt, src } => json!({"type": "image", "alt": alt, "src": src, "title": null}),
    }
}

fn inlines_json(v: &[Inline]) -> Value {
    Value::Array(v.iter().map(inline_json).collect())
}

pub fn block_json(b: &Block) -> Value {
    match b {
        Block::Paragraph { content, inline } => {
            json!({"type": "paragraph", "content": content, "inline": inlines_json(inline)})
        }
        Block::Heading { level, content, inline } => json!({
            "type": "heading", "level": level, "content": content, "inline": inlines_json(inline), "anchor": slugify(content)
        }),
        Block::Code { language, content, line } => json!({
            "type": "code", "language": language, "content": content, "start_line": line, "end_line": line
        }),
        Block::List { ordered, items } => {
            let items: Vec<Value> = items
                .iter()
                .map(|it| {
                    let mut m = Map::new();
                    m.insert("checked".into(), it.checked.map(Value::Bool).unwrap_or(Value::Null));
                    m.insert("content".into(), it.content.clone().into());
                    m.insert("inline".into(), inlines_json(&it.inline));
                    if !it.blocks.is_empty() {
                        m.insert("blocks".into(), blocks_json(&it.blocks));
                    }
                    Value::Object(m)
                })
                .collect();
            json!({"type": "list", "ordered": ordered, "items": items})
        }
        Block::Table { headers, alignments, rows } => json!({
            "type": "table", "headers": headers, "alignments": alignments, "rows": rows
        }),
        Block::Blockquote { content, blocks } => {
            json!({"type": "blockquote", "content": content, "blocks": blocks_json(blocks)})
        }
        Block::HorizontalRule => json!({"type": "horizontalrule"}),
        Block::Image { alt, src } => json!({"type": "image", "alt": alt, "src": src, "title": null}),
        Block::Details { summary, content, blocks } => json!({
            "type": "details", "summary": summary, "content": content, "blocks": blocks_json(blocks)
        }),
    }
}

pub fn blocks_json(v: &[Block]) -> Value {
    Value::Array(v.iter().map(block_json).collect())
}
