/// Wrap link destinations containing spaces in angle brackets:
/// `[text](a b)` -> `[text](<a b>)`.
pub fn preprocess_links(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::with_capacity(s.len() + 16);
    let mut i = 0;
    let mut last = 0;
    while i < b.len() {
        if b[i] == b'[' {
            // text: [^\]]+
            let mut j = i + 1;
            while j < b.len() && b[j] != b']' {
                j += 1;
            }
            if j < b.len() && j > i + 1 && j + 1 < b.len() && b[j + 1] == b'(' {
                // url: [^)<>]+ ' ' [^)<>]*  then ')'
                let us = j + 2;
                let mut k = us;
                while k < b.len() && b[k] != b')' && b[k] != b'<' && b[k] != b'>' {
                    k += 1;
                }
                if k < b.len() && b[k] == b')' {
                    let url = &s[us..k];
                    // need a space at index >= 1
                    let has_space = url.len() >= 2 && url[1..].contains(' ');
                    if has_space {
                        out.push_str(&s[last..us]);
                        out.push('<');
                        out.push_str(url);
                        out.push('>');
                        out.push(')');
                        i = k + 1;
                        last = i;
                        continue;
                    }
                }
            }
            // regex would retry at next '[' inside text; text cannot contain ']'
            // so the next candidate '[' is after i
            i += 1;
            continue;
        }
        i += 1;
    }
    out.push_str(&s[last..]);
    out
}

