pub fn heading_opts() -> md::Options {
    md::Options { tables: true, strikethrough: true, tasklists: true, heading_attributes: true, metadata: true }
}

pub fn extract_headings(content: &str) -> Vec<Heading> {
    let evs = md::parse(content, heading_opts());
    let mut out = Vec::new();
    let mut cur: Option<(u8, usize, String)> = None;
    for (e, r) in evs {
        match e {
            Event::Start(Tag::Heading { level, .. }) => cur = Some((level, r.start, String::new())),
            Event::End(Tag::Heading { .. }) => {
                if let Some((level, off, text)) = cur.take() {
                    out.push(Heading { level, text, offset: off });
                }
            }
            Event::Text(t) => {
                if let Some((_, _, s)) = cur.as_mut() {
                    s.push_str(&t);
                }
            }
            _ => {}
        }
    }
    out
}

impl Document {
    pub fn new(raw: String) -> Document {
        let needs_prefix = !(raw.trim_start().starts_with('#') || raw.contains("\n#"));
        let content = if needs_prefix { format!("# Input\n\n{}", raw) } else { raw };
        let headings = extract_headings(&content);
        Document { content, headings }
    }

    pub fn word_count(&self) -> usize {
        self.content.split_whitespace().count()
    }

    pub fn max_depth(&self) -> u8 {
        self.headings.iter().map(|h| h.level).max().unwrap_or(0)
    }

    /// Offset of the content start after a heading's first line.
    pub fn content_start(&self, h: &Heading) -> usize {
        match self.content[h.offset..].find('\n') {
            Some(p) => h.offset + p + 1,
            None => h.offset,
        }
    }

    /// 1-based line number of heading (query engine convention)
    pub fn heading_line(&self, h: &Heading) -> usize {
        self.content[..h.offset].lines().count() + 1
    }
}

/// Tree node of headings.
#[derive(Clone, Debug)]
pub struct TreeNode {
    pub idx: usize,
    pub children: Vec<TreeNode>,
}

pub fn build_tree(headings: &[Heading]) -> Vec<TreeNode> {
    fn build(headings: &[Heading], pos: &mut usize, parent_level: u8) -> Vec<TreeNode> {
        let mut out = Vec::new();
        while *pos < headings.len() {
            let h = &headings[*pos];
            if h.level <= parent_level {
                break;
            }
            let idx = *pos;
            *pos += 1;
            let children = build(headings, pos, h.level);
            out.push(TreeNode { idx, children });
        }
        out
    }
    let mut pos = 0;
    let mut out = Vec::new();
    while pos < headings.len() {
        out.extend(build(headings, &mut pos, 0));
    }
    out
}

