        if t.starts_with("```") {
            in_fence = !in_fence;
        } else if !in_fence && is_heading_like(t) {
            break;
        }
        lines.push(line);
    }
    lines.join("\n").trim().to_string()
}

fn is_heading_like(t: &str) -> bool {
    let n = t.bytes().take_while(|&c| c == b'#').count();
    if n == 0 || n > 6 {
        return false;
    }
    match t[n..].chars().next() {
        Some(c) => c.is_whitespace(),
        None => false,
    }
}
