mod blocks;
mod cli;
mod doc;
mod md;
mod output;
mod query;
mod tui;
mod util;

use doc::Document;
use std::io::{IsTerminal, Read, Write};
use std::path::{Path, PathBuf};

pub const PLACEHOLDER: &str = "# Select a file\n\nPress Enter to select a markdown file.\n";

fn no_md_files_message() {
    eprintln!("No markdown files found in current directory.");
    eprintln!();
    eprintln!("Usage: treemd [OPTIONS] <FILE>");
    eprintln!("       treemd [OPTIONS] -");
    eprintln!("       treemd [OPTIONS] .           # Open file picker");
    eprintln!("       tree | treemd [OPTIONS]");
    eprintln!();
    eprintln!("Tip: Navigate to a directory with .md files, or specify a file path.");
    eprintln!();
    eprintln!("For shell completion setup, use:");
    eprintln!("  treemd --setup-completions");
}

pub fn is_md_file(p: &Path) -> bool {
    match p.extension().and_then(|e| e.to_str()) {
        Some(e) => e == "md" || e == "markdown",
        None => false,
    }
}

fn dir_has_md(dir: &Path) -> bool {
    match std::fs::read_dir(dir) {
        Ok(rd) => rd.flatten().any(|e| {
            let p = e.path();
            p.is_file() && is_md_file(&p)
        }),
        Err(_) => false,
    }
}

pub enum Input {
    Content { text: String, path: Option<PathBuf> },
    Picker { dir: PathBuf, files: Vec<PathBuf> },
}

fn read_error(e: std::io::Error) -> ! {
    let msg = if e.kind() == std::io::ErrorKind::InvalidData {
        "stream did not contain valid UTF-8".to_string()
    } else {
        e.to_string()
    };
    eprintln!("Error reading input: I/O error: {}", msg);
    std::process::exit(1);
}

fn main() {
    let m = cli::command().get_matches();

    if m.get_flag("setup_completions") {
        let code = setup_completions();
        std::process::exit(code);
    }
    if m.get_flag("query_help") {
        print!("{}", query::QUERY_HELP);
        return;
    }

    let files: Vec<PathBuf> = m.get_many::<PathBuf>("files").map(|v| v.cloned().collect()).unwrap_or_default();

    let input = if let Some(first) = files.first() {
        if first.as_os_str() == "-" {
            let mut s = String::new();
            let mut buf = Vec::new();
            if let Err(e) = std::io::stdin().read_to_end(&mut buf) {
                read_error(e);
            }
            match String::from_utf8(buf) {
                Ok(t) => s.push_str(&t),
                Err(_) => read_error(std::io::Error::new(std::io::ErrorKind::InvalidData, "utf8")),
            }
            Input::Content { text: s, path: None }
        } else if first.is_dir() {
            Input::Picker { dir: first.clone(), files: vec![] }
        } else if files.len() > 1 && false {
            Input::Picker { dir: PathBuf::from("."), files: files.clone() }
        } else {
            match std::fs::read(first) {
                Ok(buf) => match String::from_utf8(buf) {
                    Ok(t) => Input::Content { text: t, path: Some(first.clone()) },
                    Err(_) => read_error(std::io::Error::new(std::io::ErrorKind::InvalidData, "utf8")),
                },
                Err(e) => read_error(e),
            }
        }
    } else {
        let cwd = PathBuf::from(".");
        if !dir_has_md(&cwd) {
            no_md_files_message();
            return;
        }
        Input::Picker { dir: cwd, files: vec![] }
    };

    let text = match &input {
        Input::Content { text, .. } => text.clone(),
        Input::Picker { .. } => PLACEHOLDER.to_string(),
    };
    let document = Document::new(text);

    let out = std::io::stdout();
    let mut out = out.lock();

    if let Some(q) = m.get_one::<String>("query") {
        let fmt = m.get_one::<String>("query_output").cloned().unwrap_or_else(|| "plain".into());
        let code = query::run(&document, q, &fmt, &mut out);
        let _ = out.flush();
        std::process::exit(code);
    }

    let output_fmt = m.get_one::<String>("output").cloned().unwrap_or_else(|| "plain".into());
    let filter = m.get_one::<String>("filter").cloned();
    let level = m.get_one::<usize>("level").cloned();

    if m.get_flag("count") {
        output::print_count(&document, &mut out);
        return;
    }
    if m.get_flag("tree") {
        output::print_tree_mode(&document, &output_fmt, &mut out);
        return;
    }
    if let Some(sec) = m.get_one::<String>("section") {
        let code = output::print_section(&document, sec, &mut out);
        let _ = out.flush();
        std::process::exit(code);
    }
    if m.get_flag("list") {
        output::print_list_mode(&document, &output_fmt, filter.as_deref(), level, &mut out);
        return;
    }
    if m.subcommand_matches("at-line").is_some() {
        return;
    }
    drop(out);

    // interactive mode
    let theme = m.get_one::<String>("theme").cloned();
    let color_mode = m.get_one::<String>("color_mode").cloned();
    let code = tui::run(input, document, theme, color_mode, files);
    std::process::exit(code);
}

fn setup_completions() -> i32 {
    let shell = std::env::var("SHELL").unwrap_or_default();
    let name = Path::new(&shell).file_name().and_then(|s| s.to_str()).unwrap_or("").to_string();
    let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("~"));
    let (cfg, line) = match name.as_str() {
        "bash" => (home.join(".bashrc"), "source <(COMPLETE=bash treemd)".to_string()),
        "zsh" => (home.join(".zshrc"), "source <(COMPLETE=zsh treemd)".to_string()),
        "fish" => (home.join(".config/fish/config.fish"), "COMPLETE=fish treemd | source".to_string()),
        _ => {
            println!("Shell Completion Setup Instructions");
            println!();
            println!("Add the appropriate line to your shell config:");
            println!();
            println!("Bash (~/.bashrc):");
            println!("  source <(COMPLETE=bash treemd)");
            println!();
            println!("Zsh (~/.zshrc):");
            println!("  source <(COMPLETE=zsh treemd)");
            println!();
            println!("Fish (~/.config/fish/config.fish):");
            println!("  COMPLETE=fish treemd | source");
            println!();
            println!("After adding the line, restart your shell or source the config file.");
            eprintln!("Error setting up completions: Could not detect shell");
            return 1;
        }
    };
    println!("Detected shell: {}", name);
    println!();
    // already configured?
    if let Ok(existing) = std::fs::read_to_string(&cfg) {
        if existing.contains(&line) {
            println!("Shell completions are already configured in {:?}", cfg);
            return 0;
        }
    }
    println!("To enable shell completions, add this line to {:?}:", cfg);
    println!("  {}", line);
    println!();
    print!("Would you like to add it automatically? (y/N): ");
    let _ = std::io::stdout().flush();
    let mut ans = String::new();
    let _ = std::io::stdin().read_line(&mut ans);
    if ans.trim().eq_ignore_ascii_case("y") || ans.trim().eq_ignore_ascii_case("yes") {
        let mut f = match std::fs::OpenOptions::new().create(true).append(true).open(&cfg) {
            Ok(f) => f,
            Err(e) => {
                eprintln!("Error setting up completions: {}", e);
                return 1;
            }
        };
        let _ = writeln!(f, "\n# treemd shell completions\n{}", line);
        println!();
        println!("✓ Added completion setup to {:?}", cfg);
        println!("Restart your shell or run: source {:?}", cfg);
    } else {
        println!();
        println!("Manually add the line above to enable completions.");
    }
    let _ = std::io::stdin().is_terminal();
    0
}
