use crate::blocks;
use crate::doc::{self, Document};
use serde_json::{json, Map, Value};
use std::io::Write;

pub fn hashes(level: u8) -> String {
    "#".repeat(level as usize)
}

pub fn print_count(d: &Document, out: &mut dyn Write) {
    let mut counts = [0usize; 7];
    for h in &d.headings {
        if (h.level as usize) < 7 {
            counts[h.level as usize] += 1;
        }
    }
    let _ = writeln!(out, "Heading counts:");
    for l in 1..=6 {
        if counts[l] > 0 {
            let _ = writeln!(out, "  {}: {}", "#".repeat(l), counts[l]);
        }
    }
    let _ = writeln!(out);
    let _ = writeln!(out, "Total: {}", d.headings.len());
}

fn print_tree_nodes(d: &Document, nodes: &[doc::TreeNode], prefix: &str, out: &mut dyn Write) {
    for (i, n) in nodes.iter().enumerate() {
        let last = i + 1 == nodes.len();
        let h = &d.headings[n.idx];
        let conn = if last { "└──" } else { "├──" };
        let _ = writeln!(out, "{}{}{} {}", prefix, conn, hashes(h.level), h.text);
        let np = format!("{}{}", prefix, if last { "   " } else { "│  " });
        print_tree_nodes(d, &n.children, &np, out);
    }
}

pub fn print_tree_mode(d: &Document, fmt: &str, out: &mut dyn Write) {
    if fmt == "json" {
        let arr: Vec<Value> = d.headings.iter().map(|h| json!({"level": h.level, "text": h.text})).collect();
        let _ = writeln!(out, "{}", serde_json::to_string_pretty(&Value::Array(arr)).unwrap());
        return;
    }
    let tree = doc::build_tree(&d.headings);
    print_tree_nodes(d, &tree, "", out);
}

pub fn print_list_mode(d: &Document, fmt: &str, filter: Option<&str>, level: Option<usize>, out: &mut dyn Write) {
    match fmt {
        "json" => {
            let v = document_json(d);
            let _ = writeln!(out, "{}", serde_json::to_string_pretty(&v).unwrap());
        }
        "tree" => {
            let _ = writeln!(out, "Use --tree for tree output");
        }
        _ => {
            let fl = filter.map(|f| f.to_lowercase());
            for h in &d.headings {
                if let Some(f) = &fl {
                    if !h.text.to_lowercase().contains(f.as_str()) {
                        continue;
                    }
                }
                if let Some(l) = level {
                    if h.level as usize != l {
                        continue;
                    }
                }
                let _ = writeln!(out, "{} {}", hashes(h.level), h.text);
            }
        }
    }
}

pub fn print_section(d: &Document, name: &str, out: &mut dyn Write) -> i32 {
    let q = name.to_lowercase();
    let idx = match d.headings.iter().position(|h| h.text.to_lowercase() == q) {
        Some(i) => i,
        None => {
            eprintln!("Section '{}' not found", name);
            return 1;
        }
    };
    let h = &d.headings[idx];
    let pat = format!("{} {}", hashes(h.level), h.text);
    let content = &d.content;
    if let Some(start) = content.find(&pat) {
        let end = d.headings[idx + 1..]
            .iter()
            .find(|n| n.level <= h.level)
            .and_then(|n| {
                let p2 = format!("{} {}", hashes(n.level), n.text);
                content[start..].find(&p2).map(|p| start + p)
            })
            .unwrap_or(content.len());
        let _ = writeln!(out, "{}", content[start..end].trim());
    }
    0
}

fn section_json(d: &Document, node: &doc::TreeNode) -> Value {
    let h = &d.headings[node.idx];
    let offset = d.content_start(h);
    let line = d.content[..h.offset].lines().count() + 2;
    let raw = doc::json_section_raw(&d.content, offset);
    let blocks = blocks::build_blocks(&raw, line);
    let slug = crate::util::slugify(&h.text);
    let mut m = Map::new();
    m.insert("id".into(), slug.clone().into());
    m.insert("level".into(), h.level.into());
    m.insert("title".into(), h.text.clone().into());
    m.insert("slug".into(), slug.into());
    m.insert("position".into(), json!({"line": line, "offset": offset}));
    m.insert("content".into(), json!({"raw": raw, "blocks": blocks::blocks_json(&blocks)}));
    m.insert(
        "children".into(),
        Value::Array(node.children.iter().map(|c| section_json(d, c)).collect()),
    );
    Value::Object(m)
}

pub fn document_json(d: &Document) -> Value {
    let tree = doc::build_tree(&d.headings);
    let sections: Vec<Value> = tree.iter().map(|n| section_json(d, n)).collect();
    json!({
        "document": {
            "metadata": {
                "source": null,
                "headingCount": d.headings.len(),
                "maxDepth": d.max_depth(),
                "wordCount": d.word_count(),
            },
            "sections": sections,
        }
    })
}
