//! Tokenizer for the query language.

#[derive(Clone, Debug, PartialEq)]
pub enum Tok {
    Dot,
    Ident(String),
    Number(f64),
    Str(String),
    LBracket,
    RBracket,
    LParen,
    RParen,
    LBrace,
    RBrace,
    Comma,
    Colon,
    Pipe,
    Gt,
    GtGt,
    Lt,
    Le,
    Ge,
    EqEq,
    Ne,
    Plus,
    Minus,
    Star,
    Slash,
    SlashSlash,
    Percent,
    Question,
    And,
    Or,
    Not,
    If,
    Then,
    Else,
    End,
    True,
    False,
    Null,
    Eof,
}

impl Tok {
    pub fn describe(&self) -> String {
        match self {
            Tok::Dot => "'.'".into(),
            Tok::Ident(_) => "identifier".into(),
            Tok::Number(_) => "number".into(),
            Tok::Str(_) => "string".into(),
            Tok::LBracket => "'['".into(),
            Tok::RBracket => "']'".into(),
            Tok::LParen => "'('".into(),
            Tok::RParen => "')'".into(),
            Tok::LBrace => "'{'".into(),
            Tok::RBrace => "'}'".into(),
            Tok::Comma => "','".into(),
            Tok::Colon => "':'".into(),
            Tok::Pipe => "'|'".into(),
            Tok::Gt => "'>'".into(),
            Tok::GtGt => "'>>'".into(),
            Tok::Lt => "'<'".into(),
            Tok::Le => "'<='".into(),
            Tok::Ge => "'>='".into(),
            Tok::EqEq => "'=='".into(),
            Tok::Ne => "'!='".into(),
            Tok::Plus => "'+'".into(),
            Tok::Minus => "'-'".into(),
            Tok::Star => "'*'".into(),
            Tok::Slash => "'/'".into(),
            Tok::SlashSlash => "'//'".into(),
            Tok::Percent => "'%'".into(),
            Tok::Question => "'?'".into(),
            Tok::And => "'and'".into(),
            Tok::Or => "'or'".into(),
            Tok::Not => "'not'".into(),
            Tok::If => "'if'".into(),
            Tok::Then => "'then'".into(),
            Tok::Else => "'else'".into(),
            Tok::End => "'end'".into(),
            Tok::True => "'true'".into(),
            Tok::False => "'false'".into(),
            Tok::Null => "'null'".into(),
            Tok::Eof => "end of input".into(),
        }
    }
}

#[derive(Clone, Debug)]
pub struct Token {
    pub tok: Tok,
    /// start char index
    pub start: usize,
    /// length in chars
    pub len: usize,
}

#[derive(Clone, Debug)]
pub struct QError {
    pub message: String,
    pub span: Option<(usize, usize)>,
    pub label: String,
    pub help: Option<String>,
}

impl QError {
    pub fn spanned(msg: impl Into<String>, start: usize, len: usize, label: &str) -> QError {
        QError { message: msg.into(), span: Some((start, len)), label: label.into(), help: None }
    }
    pub fn plain(msg: impl Into<String>) -> QError {
        QError { message: msg.into(), span: None, label: String::new(), help: None }
    }
    pub fn with_help(mut self, h: impl Into<String>) -> QError {
        self.help = Some(h.into());
        self
    }
}

pub fn lex(src: &str) -> Result<Vec<Token>, QError> {
    let chars: Vec<char> = src.chars().collect();
    let mut toks = Vec::new();
    let mut i = 0;
    let n = chars.len();
    while i < n {
        let c = chars[i];
        if c.is_whitespace() {
            i += 1;
            continue;
        }
        let start = i;
        let simple = |t: Tok, l: usize| Token { tok: t, start, len: l };
        match c {
            '.' => {
                toks.push(simple(Tok::Dot, 1));
                i += 1;
            }
