//! Parser producing an AST for the query language.
use super::lexer::{QError, Tok, Token};

#[derive(Clone, Debug, PartialEq, Copy)]
pub enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    Mod,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    And,
    Or,
}

#[derive(Clone, Debug)]
pub enum Pattern {
    Fuzzy(String),
    Exact(String),
}

#[derive(Clone, Debug)]
pub enum IndexFilter {
    Index(i64),
    Slice(Option<i64>, Option<i64>),
}

#[derive(Clone, Debug)]
pub struct SelectorSpec {
    pub name: String,
    pub patterns: Vec<Pattern>,
    pub index: Option<IndexFilter>,
}

#[derive(Clone, Debug)]
pub enum Expr {
    Identity,
    /// `.name` with filters; resolved at eval time as selector or property
    Field(SelectorSpec),
    /// `.a.b.c` -> property `c` of input
    Path(String),
    Literal(LitVal),
    Array(Vec<Expr>),
    Object(Vec<(String, Expr)>),
    Pipe(Box<Expr>, Box<Expr>),
    Comma(Vec<Expr>),
    Binary(BinOp, Box<Expr>, Box<Expr>),
    Not(Box<Expr>),
    Neg(Box<Expr>),
    Alt(Box<Expr>, Box<Expr>),
    If(Box<Expr>, Box<Expr>, Option<Box<Expr>>),
    Func(String, Vec<Expr>),
    Hier(Box<Expr>, SelectorSpec, bool),
}

#[derive(Clone, Debug)]
pub enum LitVal {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
}

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
}

fn expected(what: &str, t: &Token) -> QError {
    QError::spanned(format!("Expected {}, found {}", what, t.tok.describe()), t.start, t.len, "unexpected token")
}

impl Parser {
    pub fn new(toks: Vec<Token>) -> Parser {
        Parser { toks, pos: 0 }
    }

    fn peek(&self) -> &Tok {
        &self.toks[self.pos].tok
    }

    fn peek_at(&self, k: usize) -> &Tok {
        let i = (self.pos + k).min(self.toks.len() - 1);
        &self.toks[i].tok
    }

    fn cur(&self) -> &Token {
        &self.toks[self.pos]
    }

    fn advance(&mut self) -> Token {
        let t = self.toks[self.pos].clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }

    fn expect(&mut self, t: Tok, desc: &str) -> Result<Token, QError> {
        if *self.peek() == t {
            Ok(self.advance())
        } else {
            Err(expected(desc, self.cur()))
        }
    }

    pub fn parse_query(&mut self) -> Result<Expr, QError> {
        let mut items = vec![self.parse_pipeline()?];
        while *self.peek() == Tok::Comma {
            self.advance();
            items.push(self.parse_pipeline()?);
        }
        if *self.peek() != Tok::Eof {
            return Err(expected("end of query", self.cur()));
        }
        if items.len() == 1 {
            Ok(items.pop().unwrap())
        } else {
            Ok(Expr::Comma(items))
        }
    }

    pub fn parse_pipeline(&mut self) -> Result<Expr, QError> {
        let mut left = self.parse_alt()?;
        while *self.peek() == Tok::Pipe {
            self.advance();
            let right = self.parse_alt()?;
            left = Expr::Pipe(Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_alt(&mut self) -> Result<Expr, QError> {
        let mut left = self.parse_or()?;
        while *self.peek() == Tok::SlashSlash {
            self.advance();
            let right = self.parse_or()?;
            left = Expr::Alt(Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_or(&mut self) -> Result<Expr, QError> {
        let mut left = self.parse_and()?;
        while *self.peek() == Tok::Or {
            self.advance();
            let right = self.parse_and()?;
            left = Expr::Binary(BinOp::Or, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_and(&mut self) -> Result<Expr, QError> {
        let mut left = self.parse_cmp()?;
        while *self.peek() == Tok::And {
            self.advance();
            let right = self.parse_cmp()?;
            left = Expr::Binary(BinOp::And, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_cmp(&mut self) -> Result<Expr, QError> {
        let mut left = self.parse_add()?;
        loop {
            let t = self.peek().clone();
            match t {
                Tok::GtGt => {
                    self.advance();
                    let spec = self.parse_hier_child()?;
                    left = Expr::Hier(Box::new(left), spec, true);
                }
                Tok::Gt if *self.peek_at(1) == Tok::Dot => {
                    self.advance();
                    let spec = self.parse_hier_child()?;
                    left = Expr::Hier(Box::new(left), spec, false);
                }
                Tok::EqEq | Tok::Ne | Tok::Lt | Tok::Le | Tok::Gt | Tok::Ge => {
                    self.advance();
                    let op = match t {
                        Tok::EqEq => BinOp::Eq,
                        Tok::Ne => BinOp::Ne,
                        Tok::Lt => BinOp::Lt,
                        Tok::Le => BinOp::Le,
                        Tok::Gt => BinOp::Gt,
                        _ => BinOp::Ge,
                    };
                    let right = self.parse_add()?;
                    left = Expr::Binary(op, Box::new(left), Box::new(right));
                }
                _ => break,
            }
        }
        Ok(left)
    }

    fn parse_hier_child(&mut self) -> Result<SelectorSpec, QError> {
        // expect '.' ident filters
        if *self.peek() != Tok::Dot {
            return Err(expected("'.'", self.cur()));
        }
        self.advance();
        let name = match self.peek().clone() {
            Tok::Ident(n) => {
                self.advance();
                n
            }
            _ => return Err(expected("identifier", self.cur())),
        };
        let (patterns, index) = self.parse_filters()?;
        Ok(SelectorSpec { name, patterns, index })
    }

    fn parse_add(&mut self) -> Result<Expr, QError> {
        let mut left = self.parse_mul()?;
        loop {
            let op = match self.peek() {
                Tok::Plus => BinOp::Add,
                Tok::Minus => BinOp::Sub,
                _ => break,
            };
            self.advance();
            let right = self.parse_mul()?;
            left = Expr::Binary(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_mul(&mut self) -> Result<Expr, QError> {
        let mut left = self.parse_unary()?;
        loop {
            let op = match self.peek() {
                Tok::Star => BinOp::Mul,
                Tok::Slash => BinOp::Div,
                Tok::Percent => BinOp::Mod,
                _ => break,
            };
            self.advance();
            let right = self.parse_unary()?;
            left = Expr::Binary(op, Box::new(left), Box::new(right));
        }
        Ok(left)
    }

    fn parse_unary(&mut self) -> Result<Expr, QError> {
        match self.peek() {
            Tok::Not => {
                self.advance();
                let e = self.parse_unary()?;
                Ok(Expr::Not(Box::new(e)))
            }
            Tok::Minus => {
                self.advance();
                let e = self.parse_unary()?;
                Ok(Expr::Neg(Box::new(e)))
            }
            _ => self.parse_postfix(),
        }
    }

    /// Parse `[...]` filters following a selector.
    fn parse_filters(&mut self) -> Result<(Vec<Pattern>, Option<IndexFilter>), QError> {
        let mut patterns = Vec::new();
        let mut index: Option<IndexFilter> = None;
        while *self.peek() == Tok::LBracket {
            let open = self.advance();
            let t = self.cur().clone();
            match t.tok.clone() {
                Tok::RBracket => {
                    self.advance();
                }
                Tok::Ident(s) | Tok::Str(s) => {
                    let exact = matches!(t.tok, Tok::Str(_));
                    self.advance();
                    let close = self.expect(Tok::RBracket, "']'")?;
                    if index.is_some() {
                        let len = close.start + close.len - open.start;
                        return Err(QError::spanned(
                            "Invalid filter: expected index, got filter",
                            open.start,
                            len,
                            "invalid filter",
                        ));
                    }
                    patterns.push(if exact { Pattern::Exact(s) } else { Pattern::Fuzzy(s) });
                }
                Tok::Number(_) | Tok::Minus | Tok::Colon => {
                    let start = if *self.peek() == Tok::Colon { None } else { Some(self.parse_int()?) };
                    if *self.peek() == Tok::Colon {
                        self.advance();
                        let end = match self.peek() {
                            Tok::Number(_) | Tok::Minus => Some(self.parse_int()?),
                            _ => None,
                        };
                        self.expect(Tok::RBracket, "']'")?;
                        index = Some(IndexFilter::Slice(start, end));
                    } else {
                        self.expect(Tok::RBracket, "']'")?;
                        index = Some(IndexFilter::Index(start.unwrap()));
                    }
                }
                _ => {
                    return Err(QError::spanned(
                        "Invalid filter: expected filter pattern or index",
                        t.start,
                        t.len,
                        "invalid filter",
                    ));
                }
            }
        }
        Ok((patterns, index))
    }

    fn parse_int(&mut self) -> Result<i64, QError> {
        let neg = if *self.peek() == Tok::Minus {
            self.advance();
            true
        } else {
            false
        };
        match self.peek().clone() {
            Tok::Number(n) => {
                self.advance();
                let v = n as i64;
                Ok(if neg { -v } else { v })
            }
            _ => {
                let t = self.cur().clone();
                Err(QError::spanned("Invalid filter: expected filter pattern or index", t.start, t.len, "invalid filter"))
            }
        }
    }

    fn parse_postfix(&mut self) -> Result<Expr, QError> {
        let t = self.cur().clone();
        match t.tok.clone() {
            Tok::Dot => {
                self.advance();
                match self.peek().clone() {
                    Tok::Ident(name) => {
                        self.advance();
                        let (patterns, index) = self.parse_filters()?;
                        let mut expr = Expr::Field(SelectorSpec { name, patterns, index });
                        // path continuation
                        while *self.peek() == Tok::Dot {
                            if let Tok::Ident(n2) = self.peek_at(1).clone() {
                                self.advance();
                                self.advance();
                                let _ = self.parse_filters()?;
                                expr = Expr::Path(n2);
                            } else {
                                // `.` followed by non-ident: error as expected identifier
                                self.advance();
                                return Err(expected("identifier", self.cur()));
                            }
                        }
                        Ok(expr)
                    }
                    Tok::RBracket | Tok::RParen | Tok::Pipe | Tok::Comma | Tok::Eof | Tok::Gt | Tok::GtGt => {
                        Ok(Expr::Identity)
                    }
                    _ => Err(expected("identifier", self.cur())),
                }
            }
            _ => {
                let e = self.parse_primary()?;
                // postfix filters on non-selectors are parsed and ignored
                if *self.peek() == Tok::LBracket {
                    let _ = self.parse_filters()?;
                }
                Ok(e)
            }
        }
    }

    fn parse_primary(&mut self) -> Result<Expr, QError> {
        let t = self.cur().clone();
        match t.tok.clone() {
            Tok::Number(n) => {
                self.advance();
                Ok(Expr::Literal(LitVal::Num(n)))
            }
            Tok::Str(s) => {
                self.advance();
                Ok(Expr::Literal(LitVal::Str(s)))
            }
            Tok::True => {
                self.advance();
                Ok(Expr::Literal(LitVal::Bool(true)))
            }
            Tok::False => {
                self.advance();
                Ok(Expr::Literal(LitVal::Bool(false)))
            }
            Tok::Null => {
                self.advance();
                Ok(Expr::Literal(LitVal::Null))
            }
            Tok::LParen => {
                self.advance();
                let e = self.parse_pipeline()?;
                self.expect(Tok::RParen, "')'")?;
                Ok(e)
            }
            Tok::LBracket => {
                self.advance();
                let mut items = Vec::new();
                if *self.peek() != Tok::RBracket {
                    items.push(self.parse_pipeline()?);
                    while *self.peek() == Tok::Comma {
                        self.advance();
                        items.push(self.parse_pipeline()?);
                    }
                }
                self.expect(Tok::RBracket, "']'")?;
                Ok(Expr::Array(items))
            }
            Tok::LBrace => {
                self.advance();
                let mut entries = Vec::new();
                if *self.peek() != Tok::RBrace {
                    loop {
                        let key = match self.peek().clone() {
                            Tok::Ident(k) | Tok::Str(k) => {
                                self.advance();
                                k
                            }
                            _ => return Err(expected("one of identifier, string", self.cur())),
                        };
                        self.expect(Tok::Colon, "':'")?;
                        let v = self.parse_pipeline()?;
                        entries.push((key, v));
                        if *self.peek() == Tok::Comma {
                            self.advance();
                            continue;
                        }
                        break;
                    }
                }
                self.expect(Tok::RBrace, "'}'")?;
                Ok(Expr::Object(entries))
            }
            Tok::If => {
                self.advance();
                let cond = self.parse_pipeline()?;
                if *self.peek() != Tok::Then {
                    let c = self.cur().clone();
                    return Err(QError::spanned("Expected 'then' after condition", c.start, c.len, "expected 'then'"));
                }
                self.advance();
                let then = self.parse_pipeline()?;
                let mut els = None;
                if *self.peek() == Tok::Else {
                    self.advance();
                    els = Some(Box::new(self.parse_pipeline()?));
                }
                if *self.peek() != Tok::End {
                    let c = self.cur().clone();
                    return Err(QError::spanned("Expected 'end' to close conditional", c.start, c.len, "expected 'end'"));
                }
                self.advance();
                Ok(Expr::If(Box::new(cond), Box::new(then), els))
            }
            Tok::Ident(name) => {
                self.advance();
                let mut args = Vec::new();
                if *self.peek() == Tok::LParen {
                    self.advance();
                    if *self.peek() != Tok::RParen {
                        args.push(self.parse_pipeline()?);
                        while *self.peek() == Tok::Comma {
                            self.advance();
                            args.push(self.parse_pipeline()?);
                        }
                    }
                    self.expect(Tok::RParen, "')'")?;
                }
                Ok(Expr::Func(name, args))
            }
            _ => Err(expected("expression", &t)),
        }
    }
}
