cd /workspace/src/query && cat > eval.rs <<'EOF'
//! Query evaluator.
use super::lexer::QError;
use super::parser::{BinOp, Expr, IndexFilter, LitVal, Pattern, SelectorSpec};
use super::value::*;
use indexmap::IndexMap;
use std::rc::Rc;

pub struct Ctx {
    pub doc: Rc<DocumentValue>,
    pub headings: Vec<Rc<HeadingValue>>,
    /// children indices per heading (tree)
    pub children: Vec<Vec<usize>>,
    pub code: Vec<Rc<CodeValue>>,
    pub links: Vec<Rc<LinkValue>>,
    pub images: Vec<Rc<ImageValue>>,
    pub tables: Vec<Rc<TableValue>>,
    pub lists: Vec<Rc<ListValue>>,
}

type R = Result<Vec<Value>, QError>;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum SelKind {
    Heading(Option<u8>),
    Code,
    Link,
    Image,
    Table,
    List,
    Empty,
}

pub fn selector_kind(name: &str) -> Option<SelKind> {
    Some(match name {
        "h" | "heading" | "headings" | "header" | "headers" => SelKind::Heading(None),
        "h1" => SelKind::Heading(Some(1)),
        "h2" => SelKind::Heading(Some(2)),
        "h3" => SelKind::Heading(Some(3)),
        "h4" => SelKind::Heading(Some(4)),
        "h5" => SelKind::Heading(Some(5)),
        "h6" => SelKind::Heading(Some(6)),
        "code" | "codeblock" | "codeblocks" | "pre" => SelKind::Code,
        "link" | "links" | "a" | "anchor" => SelKind::Link,
        "img" | "image" | "images" => SelKind::Image,
        "table" | "tables" => SelKind::Table,
        "list" | "lists" | "ul" | "ol" => SelKind::List,
        "blockquote" | "blockquotes" | "quote" | "quotes" | "bq" | "p" | "para" | "paragraph" | "paragraphs"
        | "frontmatter" | "fm" | "meta" | "yaml" => SelKind::Empty,
        _ => return None,
    })
}

pub const FUNCTION_NAMES: &[&str] = &[
    "count", "length", "first", "last", "limit", "skip", "nth", "reverse", "sort", "sort_by", "unique", "flatten",
    "group_by", "min", "max", "add", "text", "upper", "lower", "trim", "split", "join", "replace", "slugify", "lines",
    "words", "chars", "select", "contains", "startswith", "endswith", "matches", "any", "all", "not", "content", "md",
    "url", "lang", "stats", "levels", "langs", "types", "keys", "values", "type", "has", "empty", "debug", "null",
];

fn levenshtein(a: &str, b: &str) -> usize {
    strsim::levenshtein(a, b)
}

fn suggestions(name: &str) -> Vec<String> {
    let mut c: Vec<(usize, usize, &str)> = FUNCTION_NAMES
        .iter()
        .enumerate()
        .filter_map(|(i, n)| {
            let d = levenshtein(name, n);
            if d <= 2 || n.contains(name) || name.contains(n) {
                Some((d, i, *n))
            } else {
                None
            }
        })
        .collect();
    c.sort();
    c.into_iter().take(3).map(|(_, _, n)| n.to_string()).collect()
}

fn arity(name: &str) -> Option<(usize, usize)> {
    Some(match name {
        "count" | "length" | "len" | "size" | "first" | "last" | "head" | "reverse" | "sort" | "unique" | "flatten"
        | "min" | "max" | "add" | "text" | "upper" | "lower" | "trim" | "slugify" | "lines" | "words" | "chars"
        | "content" | "md" | "markdown" | "url" | "href" | "src" | "lang" | "language" | "stats" | "levels"
        | "langs" | "types" | "keys" | "values" | "type" | "empty" | "ascii_downcase" | "ascii_upcase" | "debug" => {
            (0, 0)
        }
        "limit" | "take" | "skip" | "drop" | "nth" | "sort_by" | "group_by" | "group" | "split" | "join" | "select"
        | "where" | "filter" | "contains" | "includes" | "startswith" | "starts_with" | "endswith" | "ends_with"
        | "matches" | "any" | "all" | "has" => (1, 1),
        "replace" => (2, 2),
        _ => return None,
    })
}

fn collapse(mut v: Vec<Value>) -> Value {
    if v.len() == 1 {
        v.pop().unwrap()
    } else {
        Value::Array(v)
    }
}

fn first_or_null(v: Vec<Value>) -> Value {
    v.into_iter().next().unwrap_or(Value::Null)
}

fn not_found(name: &str, v: &Value) -> QError {
    QError::plain(format!("Property '{}' not found on {}", name, v.type_name()))
}

fn num(n: usize) -> Value {
    Value::Number(n as f64)
}

fn s(x: &str) -> Value {
    Value::String(x.to_string())
}

fn opt_s(x: &Option<String>) -> Value {
    match x {
        Some(v) => Value::String(v.clone()),
        None => Value::Null,
    }
}

impl Ctx {
    fn all_of(&self, kind: SelKind) -> Vec<Value> {
        match kind {
            SelKind::Heading(lvl) => self
                .headings
                .iter()
                .filter(|h| lvl.map_or(true, |l| h.level == l))
                .map(|h| Value::Heading(h.clone()))
                .collect(),
            SelKind::Code => self.code.iter().map(|c| Value::Code(c.clone())).collect(),
            SelKind::Link => self.links.iter().map(|c| Value::Link(c.clone())).collect(),
            SelKind::Image => self.images.iter().map(|c| Value::Image(c.clone())).collect(),
            SelKind::Table => self.tables.iter().map(|c| Value::Table(c.clone())).collect(),
            SelKind::List => self.lists.iter().map(|c| Value::List(c.clone())).collect(),
            SelKind::Empty => vec![],
        }
    }

    fn apply_filters(&self, mut items: Vec<Value>, spec: &SelectorSpec) -> Vec<Value> {
        for p in &spec.patterns {
            items.retain(|v| pattern_match(v, p));
        }
        if let Some(ix) = &spec.index {
            items = apply_index(items, ix);
        }
        items
    }

    pub fn eval(&self, e: &Expr, input: &Value) -> R {
        match e {
            Expr::Identity => Ok(vec![input.clone()]),
            Expr::Literal(l) => Ok(vec![match l {
                LitVal::Null => Value::Null,
                LitVal::Bool(b) => Value::Bool(*b),
                LitVal::Num(n) => Value::Number(*n),
                LitVal::Str(st) => Value::String(st.clone()),
            }]),
            Expr::Field(spec) => {
                if let Some(kind) = selector_kind(&spec.name) {
                    let items = self.all_of(kind);
                    Ok(self.apply_filters(items, spec))
                } else {
                    Ok(vec![self.property(input, &spec.name)?])
                }
            }
            Expr::Path(name) => Ok(vec![self.property(input, name)?]),
            Expr::Array(items) => {
                let mut out = Vec::new();
                for it in items {
                    out.extend(self.eval(it, input)?);
                }
                Ok(vec![Value::Array(out)])
            }
            Expr::Object(entries) => {
                let mut m = IndexMap::new();
                for (k, v) in entries {
                    let r = self.eval(v, input)?;
                    m.insert(k.clone(), collapse(r));
                }
                Ok(vec![Value::Object(m)])
            }
            Expr::Pipe(a, b) => {
                let left = self.eval(a, input)?;
                let mut out = Vec::new();
                for v in left {
                    out.extend(self.eval(b, &v)?);
                }
                Ok(out)
            }
            Expr::Comma(items) => {
                let mut out = Vec::new();
                for it in items {
                    out.extend(self.eval(it, input)?);
                }
                Ok(out)
            }
            Expr::Binary(op, a, b) => {
                let l = first_or_null(self.eval(a, input)?);
                let r = first_or_null(self.eval(b, input)?);
                Ok(vec![binop(*op, &l, &r)?])
            }
            Expr::Not(a) => {
                let v = first_or_null(self.eval(a, input)?);
                Ok(vec![Value::Bool(!v.truthy())])
            }
            Expr::Neg(a) => {
                let v = first_or_null(self.eval(a, input)?);
                Ok(vec![match v {
                    Value::Number(n) => Value::Number(-n),
                    _ => Value::Null,
                }])
            }
            Expr::Alt(a, b) => {
                let l = first_or_null(self.eval(a, input)?);
                if l.truthy() {
                    Ok(vec![l])
                } else {
                    self.eval(b, input)
                }
            }
            Expr::If(c, t, el) => {
                let cv = first_or_null(self.eval(c, input)?);
                if cv.truthy() {
                    self.eval(t, input)
                } else if let Some(el) = el {
                    self.eval(el, input)
                } else {
                    Ok(vec![Value::Null])
                }
            }
            Expr::Hier(parent, spec, desc) => {
                let parents = self.eval(parent, input)?;
                let kind = selector_kind(&spec.name);
                let mut out = Vec::new();
                for p in parents {
                    if let Value::Heading(h) = &p {
                        match kind {
                            Some(SelKind::Heading(lvl)) => {
                                let mut idxs = Vec::new();
                                if *desc {
                                    self.descendants(h.index, &mut idxs);
                                } else {
                                    idxs = self.children[h.index].clone();
                                }
                                for i in idxs {
                                    let c = &self.headings[i];
                                    if lvl.map_or(true, |l| c.level == l) {
                                        out.push(Value::Heading(c.clone()));
                                    }
                                }
                            }
                            Some(SelKind::Code) => {
                                out.extend(self.all_of(SelKind::Code));
                            }
                            _ => {}
                        }
                    }
                }
                Ok(self.apply_filters(out, spec))
            }
            Expr::Func(name, args) => self.call(name, args, input),
        }
    }

    fn descendants(&self, i: usize, out: &mut Vec<usize>) {
        for &c in &self.children[i] {
            out.push(c);
            self.descendants(c, out);
        }
    }

    fn property(&self, v: &Value, name: &str) -> Result<Value, QError> {
        let r = match v {
            Value::Object(o) => o.get(name).cloned(),
            Value::Heading(h) => match name {
                "text" => Some(s(&h.text)),
                "content" => Some(s(&h.content)),
                "level" => Some(num(h.level as usize)),
                "line" => Some(num(h.line)),
                "md" => Some(s(&h.raw_md)),
                "slug" => Some(s(&crate::util::slugify(&h.text))),
                "offset" => Some(num(h.offset)),
                _ => None,
            },
            Value::Code(c) => match name {
                "text" | "content" => Some(s(&c.content)),
                "lang" | "language" => Some(opt_s(&c.language)),
                "start_line" => Some(num(c.start_line)),
                "end_line" => Some(num(c.end_line)),
                "lines" => Some(num(c.content.lines().count())),
                _ => None,
            },
            Value::Link(l) => match name {
                "text" => Some(s(&l.text)),
                "url" => Some(s(&l.url)),
                "type" => Some(s(l.link_type.as_str())),
                "offset" => Some(num(l.offset)),
                _ => None,
            },
            Value::Image(i) => match name {
                "alt" => Some(s(&i.alt)),
                "src" | "url" => Some(s(&i.src)),
                "title" => Some(opt_s(&i.title)),
                _ => None,
            },
            Value::Table(t) => match name {
                "rows" => Some(Value::Array(
                    t.rows.iter().map(|r| Value::Array(r.iter().map(|c| s(c)).collect())).collect(),
                )),
                "columns" | "cols" => Some(num(t.headers.len())),
                "alignments" => Some(Value::Array(t.alignments.iter().map(|a| s(a)).collect())),
                _ => None,
            },
            Value::List(l) => match name {
                "items" => Some(Value::Array(l.items.iter().map(|i| s(&i.content)).collect())),
                "ordered" => Some(Value::Bool(l.ordered)),
                "count" | "length" => Some(num(l.items.len())),
                _ => None,
            },
            Value::Document(d) => match name {
                "text" | "content" => Some(s(&d.content)),
                "words" | "word_count" => Some(num(d.word_count)),
                "heading_count" => Some(num(d.heading_count)),
                _ => None,
            },
            _ => None,
        };
        r.ok_or_else(|| not_found(name, v))
    }

    fn arg(&self, args: &[Expr], i: usize, input: &Value) -> Result<Value, QError> {
        Ok(collapse(self.eval(&args[i], input)?))
    }

    fn call(&self, name: &str, args: &[Expr], input: &Value) -> R {
        let (lo, hi) = match arity(name) {
            Some(a) => a,
            None => {
                let sug = suggestions(name);
                let mut err = QError::plain(format!("Unknown function '{}'", name));
                if !sug.is_empty() {
                    let list = sug.iter().map(|s| format!("'{}'", s)).collect::<Vec<_>>().join(" or ");
                    err = err.with_help(format!("did you mean {}?", list));
                }
                return Err(err);
            }
        };
        if args.len() < lo || args.len() > hi {
            return Err(QError::plain(format!(
                "Function '{}' expects {}..={} arguments, got {}",
                name,
                lo,
                hi,
                args.len()
            )));
        }
        let v = input;
        let one = |x: Value| -> R { Ok(vec![x]) };
        match name {
            "count" | "length" | "len" | "size" => one(num(match v {
                Value::Array(a) => a.len(),
                Value::Object(o) => o.len(),
                Value::String(st) => st.chars().count(),
                _ => 1,
            })),
            "first" | "head" => match v {
                Value::Array(a) => Ok(a.first().cloned().into_iter().collect()),
                Value::String(st) => Ok(st.chars().next().map(|c| Value::String(c.to_string())).into_iter().collect()),
                _ => one(v.clone()),
            },
            "last" => match v {
                Value::Array(a) => Ok(a.last().cloned().into_iter().collect()),
                Value::String(st) => Ok(st.chars().last().map(|c| Value::String(c.to_string())).into_iter().collect()),
                _ => one(v.clone()),
            },
            "limit" | "take" => {
                let n = self.arg(args, 0, v)?;
                match v {
                    Value::Array(a) => {
                        let k = match n {
                            Value::Number(x) if x > 0.0 => x as usize,
                            _ => 0,
                        };
                        one(Value::Array(a.iter().take(k).cloned().collect()))
                    }
                    _ => one(v.clone()),
                }
            }
            "skip" | "drop" => {
                let n = self.arg(args, 0, v)?;
                match v {
                    Value::Array(a) => {
                        let k = match n {
                            Value::Number(x) if x > 0.0 => x as usize,
                            _ => 0,
                        };
                        one(Value::Array(a.iter().skip(k).cloned().collect()))
                    }
                    _ => one(v.clone()),
                }
            }
            "nth" => {
                let n = self.arg(args, 0, v)?;
                match (v, n) {
                    (Value::Array(a), Value::Number(x)) => {
                        let i = x as i64;
                        let idx = if i < 0 { a.len() as i64 + i } else { i };
                        if idx >= 0 && (idx as usize) < a.len() {
                            one(a[idx as usize].clone())
                        } else {
                            Ok(vec![])
                        }
                    }
                    (Value::Array(_), _) => Ok(vec![]),
                    _ => one(v.clone()),
                }
            }
            "reverse" => match v {
                Value::Array(a) => one(Value::Array(a.iter().rev().cloned().collect())),
                Value::String(st) => one(Value::String(st.chars().rev().collect())),
                _ => one(v.clone()),
            },
            "sort" => match v {
                Value::Array(a) => {
                    let mut b = a.clone();
                    b.sort_by(|x, y| x.to_text().cmp(&y.to_text()));
                    one(Value::Array(b))
                }
                _ => one(v.clone()),
            },
            "sort_by" => {
                let key = self.arg(args, 0, v)?;
                match v {
                    Value::Array(a) => {
                        let k = key.to_text();
                        let mut b = a.clone();
                        b.sort_by(|x, y| sort_key(x, &k).cmp(&sort_key(y, &k)));
                        one(Value::Array(b))
                    }
                    _ => one(v.clone()),
                }
            }
            "unique" => match v {
                Value::Array(a) => {
                    let mut seen = std::collections::HashSet::new();
                    let mut b = Vec::new();
                    for x in a {
                        if seen.insert(x.to_text()) {
                            b.push(x.clone());
                        }
                    }
                    one(Value::Array(b))
                }
                _ => one(v.clone()),
            },
            "flatten" => match v {
                Value::Array(a) => {
                    let mut b = Vec::new();
                    for x in a {
                        match x {
                            Value::Array(inner) => b.extend(inner.iter().cloned()),
                            _ => b.push(x.clone()),
                        }
                    }
                    one(Value::Array(b))
                }
                _ => one(v.clone()),
            },
            "group_by" | "group" => {
                let key = self.arg(args, 0, v)?;
                match v {
                    Value::Array(a) => {
                        let k = key.to_text();
                        let mut m: IndexMap<String, Value> = IndexMap::new();
                        for x in a {
                            let gk = group_key(x, &k);
                            match m.get_mut(&gk) {
                                Some(Value::Array(arr)) => arr.push(x.clone()),
                                _ => {
                                    m.insert(gk, Value::Array(vec![x.clone()]));
                                }
                            }
                        }
                        one(Value::Object(m))
                    }
                    _ => one(v.clone()),
                }
            }
            "min" | "max" => match v {
                Value::Number(_) => one(v.clone()),
                Value::Array(a) => {
                    let nums: Vec<f64> = a
                        .iter()
                        .filter_map(|x| if let Value::Number(n) = x { Some(*n) } else { None })
                        .collect();
                    if nums.is_empty() {
                        one(Value::Null)
                    } else {
                        let r = if name == "min" {
                            nums.iter().cloned().fold(f64::INFINITY, f64::min)
                        } else {
                            nums.iter().cloned().fold(f64::NEG_INFINITY, f64::max)
                        };
                        one(Value::Number(r))
                    }
                }
                _ => one(Value::Null),
            },
            "add" => match v {
                Value::Array(a) => {
                    if a.iter().all(|x| matches!(x, Value::Number(_))) {
                        let sum: f64 = a.iter().map(|x| if let Value::Number(n) = x { *n } else { 0.0 }).sum();
                        one(Value::Number(sum))
                    } else {
                        one(Value::String(a.iter().map(|x| x.to_text()).collect::<String>()))
                    }
                }
                _ => one(v.clone()),
            },
            "text" => one(Value::String(v.to_text())),
            "upper" | "ascii_upcase" => one(Value::String(if name == "upper" {
                v.to_text().to_uppercase()
            } else {
                v.to_text().to_ascii_uppercase()
            })),
            "lower" | "ascii_downcase" => one(Value::String(if name == "lower" {
                v.to_text().to_lowercase()
            } else {
                v.to_text().to_ascii_lowercase()
            })),
            "trim" => one(Value::String(v.to_text().trim().to_string())),
            "split" => {
                let sep = self.arg(args, 0, v)?.to_text();
                let t = v.to_text();
                let parts: Vec<Value> = if sep.is_empty() {
                    t.split("").map(|p| Value::String(p.to_string())).collect()
                } else {
                    t.split(sep.as_str()).map(|p| Value::String(p.to_string())).collect()
                };
                one(Value::Array(parts))
            }
            "join" => {
                let sep = self.arg(args, 0, v)?.to_text();
                match v {
                    Value::Array(a) => one(Value::String(a.iter().map(|x| x.to_text()).collect::<Vec<_>>().join(&sep))),
                    _ => one(Value::String(v.to_text())),
                }
            }
            "replace" => {
                let a = self.arg(args, 0, v)?.to_text();
                let b = self.arg(args, 1, v)?.to_text();
                one(Value::String(v.to_text().replace(a.as_str(), &b)))
            }
            "slugify" => one(Value::String(crate::util::slugify(&v.to_text()))),
            "lines" => one(num(v.to_text().lines().count())),
            "words" => one(num(v.to_text().split_whitespace().count())),
            "chars" => one(num(v.to_text().chars().count())),
            "select" | "where" | "filter" => {
                let c = self.arg(args, 0, v)?;
                if c.truthy() {
                    one(v.clone())
                } else {
                    Ok(vec![])
                }
            }
            "contains" | "includes" => {
                let a = self.arg(args, 0, v)?.to_text().to_lowercase();
                one(Value::Bool(v.to_text().to_lowercase().contains(&a)))
            }
            "startswith" | "starts_with" => {
                let a = self.arg(args, 0, v)?.to_text().to_lowercase();
                one(Value::Bool(v.to_text().to_lowercase().starts_with(&a)))
            }
            "endswith" | "ends_with" => {
                let a = self.arg(args, 0, v)?.to_text().to_lowercase();
                one(Value::Bool(v.to_text().to_lowercase().ends_with(&a)))
            }
            "matches" => {
                let pat = self.arg(args, 0, v)?.to_text();
                match regex::Regex::new(&pat) {
                    Ok(re) => one(Value::Bool(re.is_match(&v.to_text()))),
                    Err(e) => Err(QError::plain(format!("Invalid regex '{}': {}", pat, e))),
                }
            }
            "any" | "all" => match v {
                Value::Array(a) => {
                    let r = if name == "any" { a.iter().any(|x| x.truthy()) } else { a.iter().all(|x| x.truthy()) };
                    one(Value::Bool(r))
                }
                _ => {
                    let c = self.arg(args, 0, v)?;
                    one(Value::Bool(c.truthy()))
                }
            },
            "content" => match v {
                Value::Heading(h) => one(s(&h.content)),
                _ => one(Value::String(v.to_text())),
            },
            "md" | "markdown" => match v {
                Value::Heading(h) => one(s(&h.raw_md)),
                _ => one(Value::String(v.to_text())),
            },
            "url" | "href" | "src" => match v {
                Value::Link(l) => one(s(&l.url)),
                Value::Image(i) => one(s(&i.src)),
                _ => one(Value::Null),
            },
            "lang" | "language" => match v {
                Value::Code(c) => one(opt_s(&c.language)),
                _ => one(Value::Null),
            },
            "stats" => {
                let mut m = IndexMap::new();
                m.insert("headings".to_string(), num(self.headings.len()));
                m.insert("code_blocks".to_string(), num(self.code.len()));
                m.insert("links".to_string(), num(self.links.len()));
                m.insert("images".to_string(), num(self.images.len()));
                m.insert("tables".to_string(), num(self.tables.len()));
                m.insert("lists".to_string(), num(self.lists.len()));
                m.insert("words".to_string(), num(self.doc.word_count));
                one(Value::Object(m))
            }
            "levels" => {
                let mut m = IndexMap::new();
                for l in 1..=6u8 {
                    let c = self.headings.iter().filter(|h| h.level == l).count();
                    if c > 0 {
                        m.insert(format!("h{}", l), num(c));
                    }
                }
                one(Value::Object(m))
            }
            "langs" => {
                let mut m: IndexMap<String, Value> = IndexMap::new();
                for c in &self.code {
                    let k = c.language.clone().unwrap_or_else(|| "none".to_string());
                    let e = m.entry(k).or_insert(Value::Number(0.0));
                    if let Value::Number(n) = e {
                        *n += 1.0;
                    }
                }
                one(Value::Object(m))
            }
            "types" => {
                let mut m: IndexMap<String, Value> = IndexMap::new();
                for l in &self.links {
                    let e = m.entry(l.link_type.as_str().to_string()).or_insert(Value::Number(0.0));
                    if let Value::Number(n) = e {
                        *n += 1.0;
                    }
                }
                one(Value::Object(m))
            }
            "keys" => match v {
                Value::Object(o) => one(Value::Array(o.keys().map(|k| s(k)).collect())),
                Value::Array(a) => one(Value::Array((0..a.len()).map(num).collect())),
                _ => one(Value::Array(vec![])),
            },
            "values" => match v {
                Value::Object(o) => one(Value::Array(o.values().cloned().collect())),
                Value::Array(a) => one(Value::Array(a.clone())),
                _ => one(Value::Array(vec![])),
            },
            "type" => one(s(v.type_name())),
            "has" => {
                let k = self.arg(args, 0, v)?.to_text();
                match v {
                    Value::Object(o) => one(Value::Bool(o.contains_key(&k))),
                    _ => one(Value::Bool(false)),
                }
            }
            "empty" => one(Value::Bool(match v {
                Value::Null => true,
                Value::String(st) => st.is_empty(),
                Value::Array(a) => a.is_empty(),
                Value::Object(o) => o.is_empty(),
                _ => false,
            })),
            "debug" => {
                eprintln!("[DEBUG] {:?}", v);
                one(v.clone())
            }
            _ => Ok(vec![]),
        }
    }
}

fn sort_key(v: &Value, key: &str) -> String {
    match v {
        Value::Object(o) => o.get(key).map(|x| x.to_text()).unwrap_or_default(),
        _ => v.to_text(),
    }
}

fn group_key(v: &Value, key: &str) -> String {
    match v {
        Value::Heading(h) => format!("h{}", h.level),
        Value::Code(c) => c.language.clone().unwrap_or_else(|| "none".to_string()),
        Value::Object(o) => o.get(key).map(|x| x.to_text()).unwrap_or_default(),
        _ => v.to_text(),
    }
}

fn pattern_match(v: &Value, p: &Pattern) -> bool {
    match p {
        Pattern::Fuzzy(pat) => {
            if let Value::Link(l) = v {
                match pat.as_str() {
                    "external" => return l.link_type == LinkType::External,
                    "anchor" => return l.link_type == LinkType::Anchor,
                    "relative" => return l.link_type == LinkType::Relative,
                    "wikilink" => return l.link_type == LinkType::WikiLink,
                    _ => {}
                }
            }
            v.to_text().to_lowercase().contains(&pat.to_lowercase())
        }
        Pattern::Exact(pat) => v.to_text().to_lowercase() == pat.to_lowercase(),
    }
}

fn apply_index(items: Vec<Value>, ix: &IndexFilter) -> Vec<Value> {
    let n = items.len() as i64;
    let norm = |i: i64| -> i64 {
        if i < 0 {
            (n + i).max(0)
        } else {
            i.min(n)
        }
    };
    match ix {
        IndexFilter::Index(i) => {
            let idx = if *i < 0 { n + *i } else { *i };
            if idx >= 0 && idx < n {
                vec![items[idx as usize].clone()]
            } else {
                vec![]
            }
        }
        IndexFilter::Slice(a, b) => {
            let s = norm(a.unwrap_or(0));
            let e = norm(b.unwrap_or(n));
            if s >= e {
                vec![]
            } else {
                items[s as usize..e as usize].to_vec()
            }
        }
    }
}

fn binop(op: BinOp, l: &Value, r: &Value) -> Result<Value, QError> {
    Ok(match op {
        BinOp::And => Value::Bool(l.truthy() && r.truthy()),
        BinOp::Or => Value::Bool(l.truthy() || r.truthy()),
        BinOp::Eq => Value::Bool(l.to_text() == r.to_text()),
        BinOp::Ne => Value::Bool(l.to_text() != r.to_text()),
        BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
            let ord = match (l, r) {
                (Value::Number(a), Value::Number(b)) => a.partial_cmp(b),
                (Value::String(a), Value::String(b)) => Some(a.cmp(b)),
                _ => None,
            };
            match ord {
                None => Value::Bool(false),
                Some(o) => Value::Bool(match op {
                    BinOp::Lt => o == std::cmp::Ordering::Less,
                    BinOp::Le => o != std::cmp::Ordering::Greater,
                    BinOp::Gt => o == std::cmp::Ordering::Greater,
                    _ => o != std::cmp::Ordering::Less,
                }),
            }
        }
        BinOp::Add => match (l, r) {
            (Value::Number(a), Value::Number(b)) => Value::Number(a + b),
            (Value::Array(a), Value::Array(b)) => {
                let mut c = a.clone();
                c.extend(b.iter().cloned());
                Value::Array(c)
            }
            _ => Value::String(format!("{}{}", l.to_text(), r.to_text())),
        },
        BinOp::Sub => match (l, r) {
            (Value::Number(a), Value::Number(b)) => Value::Number(a - b),
            _ => Value::Null,
        },
        BinOp::Mul => match (l, r) {
            (Value::Number(a), Value::Number(b)) => Value::Number(a * b),
            (Value::String(a), Value::Number(b)) | (Value::Number(b), Value::String(a)) => {
                let k = if *b > 0.0 { *b as usize } else { 0 };
                Value::String(a.repeat(k))
            }
            _ => Value::Null,
        },
        BinOp::Div => match (l, r) {
            (Value::Number(a), Value::Number(b)) => {
                if *b == 0.0 {
                    return Err(QError::plain("Division by zero"));
                }
                Value::Number(a / b)
            }
            _ => Value::Null,
        },
        BinOp::Mod => match (l, r) {
            (Value::Number(a), Value::Number(b)) => {
                if *b == 0.0 {
                    return Err(QError::plain("Division by zero"));
                }
                Value::Number(a % b)
            }
            _ => Value::Null,
        },
    })
}
