//! The tql query language.
pub mod eval;
pub mod lexer;
pub mod parser;
pub mod value;

use crate::blocks::{self, Block};
use crate::doc::{self, Document};
use crate::md::{self, Event, LinkKind, Tag};
use eval::Ctx;
use lexer::QError;
use std::io::Write;
use std::rc::Rc;
use value::*;

pub const QUERY_HELP: &str = include_str!("help.txt");

fn classify(url: &str) -> LinkType {
    if url.starts_with("http://") || url.starts_with("https://") || url.starts_with("mailto:") {
        LinkType::External
    } else if url.starts_with('#') {
        LinkType::Anchor
    } else {
        LinkType::Relative
    }
}

pub fn extract_links(content: &str) -> Vec<LinkValue> {
    let mut opts = doc::heading_opts();
    opts.wikilinks = true;
    let evs = md::parse(content, opts);
    let mut out = Vec::new();
    let mut stack: Vec<(String, LinkKind, usize, String)> = Vec::new();
    for (e, r) in evs {
        match e {
            Event::Start(Tag::Link { dest, kind, .. }) => stack.push((dest, kind, r.start, String::new())),
            Event::End(Tag::Link { .. }) => {
                if let Some((dest, kind, off, text)) = stack.pop() {
                    let lt = if kind == LinkKind::WikiLink { LinkType::WikiLink } else { classify(&dest) };
                    out.push(LinkValue { text, url: dest, link_type: lt, offset: off });
                }
            }
            Event::Text(t) | Event::Code(t) => {
                if let Some(top) = stack.last_mut() {
                    top.3.push_str(&t);
                }
            }
            _ => {}
        }
    }
    out
}

fn collect_blocks(blocks: &[Block], ctx: &mut Ctx) {
    for b in blocks {
        match b {
            Block::Code { language, content, line } => ctx.code.push(Rc::new(CodeValue {
                language: language.clone(),
                content: content.clone(),
                start_line: *line,
                end_line: *line,
            })),
            Block::List { ordered, items } => {
                for it in items {
                    for ib in &it.blocks {
                        if let Block::Code { language, content, line } = ib {
                            ctx.code.push(Rc::new(CodeValue {
                                language: language.clone(),
                                content: content.clone(),
                                start_line: *line,
                                end_line: *line,
                            }));
                        }
                    }
                }
                ctx.lists.push(Rc::new(ListValue {
                    ordered: *ordered,
                    items: items
                        .iter()
                        .map(|i| ListItemValue { content: i.content.clone(), checked: i.checked })
                        .collect(),
                }));
            }
            Block::Table { headers, alignments, rows } => ctx.tables.push(Rc::new(TableValue {
                headers: headers.clone(),
                rows: rows.clone(),
                alignments: alignments.clone(),
            })),
            Block::Image { alt, src } => {
                ctx.images.push(Rc::new(ImageValue { alt: alt.clone(), src: src.clone(), title: None }))
            }
            _ => {}
        }
    }
}

pub fn build_ctx(d: &Document) -> Ctx {
    let content = &d.content;
    let hs = &d.headings;
    let mut headings = Vec::new();
    for (i, h) in hs.iter().enumerate() {
        let next = hs[i + 1..].iter().find(|n| n.level <= h.level).map(|n| n.offset).unwrap_or(content.len());
        let cs = d.content_start(h).min(next.max(h.offset));
        let body = if cs <= next { &content[cs..next] } else { "" };
        headings.push(Rc::new(HeadingValue {
            level: h.level,
            text: h.text.clone(),
            offset: h.offset,
            line: d.heading_line(h),
            content: body.trim().to_string(),
            raw_md: content[h.offset..next].to_string(),
            index: i,
        }));
    }
    let tree = doc::build_tree(hs);
    let mut children = vec![Vec::new(); hs.len()];
    fn walk(nodes: &[doc::TreeNode], children: &mut Vec<Vec<usize>>) {
        for n in nodes {
            children[n.idx] = n.children.iter().map(|c| c.idx).collect();
            walk(&n.children, children);
        }
    }
    walk(&tree, &mut children);
    let docv = Rc::new(DocumentValue {
        content: content.clone(),
        heading_count: hs.len(),
        word_count: d.word_count(),
    });
    let mut ctx = Ctx {
        doc: docv,
        headings,
        children,
        code: vec![],
        links: extract_links(content).into_iter().map(Rc::new).collect(),
        images: vec![],
        tables: vec![],
        lists: vec![],
    };
    let blocks = blocks::build_blocks(content, 1);
    collect_blocks(&blocks, &mut ctx);
    ctx
}

pub fn format_error(q: &str, e: &QError) -> String {
    let mut out = format!("error: {}\n", e.message);
    if let Some((start, len)) = e.span {
        out.push_str("  --> query\n  |\n");
        out.push_str(&format!("1 | {}\n", q));
        out.push_str(&format!("    {}{}  {}\n", " ".repeat(start), "^".repeat(len.max(1)), e.label));
        if let Some(h) = &e.help {
            out.push_str(&format!("  = help: {}\n", h));
        }
    } else if let Some(h) = &e.help {
        out.push_str("  |\n");
        out.push_str(&format!("  = help: {}\n", h));
    }
    out
}

pub fn run(d: &Document, q: &str, fmt: &str, out: &mut dyn Write) -> i32 {
    let fmt_l = fmt.to_lowercase();
    let toks = match lexer::lex(q) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("{}", format_error(q, &e));
            return 1;
        }
    };
    let mut p = parser::Parser::new(toks);
    let expr = match p.parse_query() {
        Ok(e) => e,
        Err(e) => {
            eprintln!("{}", format_error(q, &e));
            return 1;
        }
    };
    if !matches!(fmt_l.as_str(), "plain" | "json" | "json-pretty" | "jsonl" | "md" | "tree") {
        eprintln!("Error: Unknown output format: {}", fmt);
        return 1;
    }
    let ctx = build_ctx(d);
    let input = Value::Document(ctx.doc.clone());
    let results = match ctx.eval(&expr, &input) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("{}", format_error(q, &e));
            return 1;
        }
    };
    if results.is_empty() {
        return 0;
    }
    match fmt_l.as_str() {
        "plain" => {
            for r in &results {
                let _ = writeln!(out, "{}", r.to_plain());
            }
        }
        "md" => {
            let parts: Vec<String> = results.iter().map(|r| r.to_md()).collect();
            let _ = writeln!(out, "{}", parts.join("\n\n"));
        }
        "tree" => {
            let mut s = String::new();
            let n = results.len();
            for (i, r) in results.iter().enumerate() {
                r.write_tree("", i + 1 == n, &mut s);
            }
            let _ = writeln!(out, "{}", s);
        }
        "json" | "json-pretty" => {
            let v = if results.len() == 1 {
                results[0].to_json()
            } else {
                serde_json::Value::Array(results.iter().map(|r| r.to_json()).collect())
            };
            let s = if fmt_l == "json" { serde_json::to_string(&v) } else { serde_json::to_string_pretty(&v) };
            let _ = writeln!(out, "{}", s.unwrap_or_default());
        }
        "jsonl" => {
            for r in &results {
                let _ = writeln!(out, "{}", serde_json::to_string(&r.to_json()).unwrap_or_default());
            }
        }
        _ => {}
    }
    0
}
