//! Render content blocks into styled lines.
use super::theme::Theme;
use crate::blocks::{Block, Inline, ListItem};
use ratatui::style::{Modifier, Style};
use ratatui::text::{Line, Span};
use unicode_width::UnicodeWidthStr;

pub const IMAGE_HEIGHT: usize = 14;

fn inline_spans(inl: &[Inline], t: &Theme) -> (Vec<Span<'static>>, usize) {
    let mut spans = Vec::new();
    let mut images = 0;
    for i in inl {
        match i {
            Inline::Text(s) => spans.push(Span::styled(s.clone(), Style::default().fg(t.fg))),
            Inline::Emphasis(s) => {
                spans.push(Span::styled(s.clone(), Style::default().fg(t.emphasis).add_modifier(Modifier::ITALIC)))
            }
            Inline::Strong(s) => {
                spans.push(Span::styled(s.clone(), Style::default().fg(t.strong).add_modifier(Modifier::BOLD)))
            }
            Inline::Strikethrough(s) => spans
                .push(Span::styled(s.clone(), Style::default().fg(t.strike).add_modifier(Modifier::CROSSED_OUT))),
            Inline::Code(s) => spans.push(Span::styled(s.clone(), Style::default().fg(t.code_fg).bg(t.code_bg))),
            Inline::Link { text, .. } => {
                spans.push(Span::styled(text.clone(), Style::default().fg(t.link).add_modifier(Modifier::UNDERLINED)))
            }
            Inline::Image { .. } => {
                images += 1;
            }
        }
    }
    (spans, images)
}

fn spans_text(spans: &[Span]) -> String {
    spans.iter().map(|s| s.content.as_ref()).collect()
}

fn truncate_to(s: &str, w: usize) -> String {
    let mut out = String::new();
    let mut cur = 0;
    for c in s.chars() {
        let cw = unicode_width::UnicodeWidthChar::width(c).unwrap_or(0);
        if cur + cw > w {
            break;
        }
        out.push(c);
        cur += cw;
    }
    out
}

fn table_lines(headers: &[String], aligns: &[String], rows: &[Vec<String>], t: &Theme) -> Vec<Line<'static>> {
    const MAX_W: usize = 10;
    let ncols = headers.len();
    let mut widths = vec![0usize; ncols];
    for (i, h) in headers.iter().enumerate() {
        widths[i] = widths[i].max(UnicodeWidthStr::width(h.as_str()));
    }
    for r in rows {
        for (i, c) in r.iter().enumerate().take(ncols) {
            widths[i] = widths[i].max(UnicodeWidthStr::width(c.as_str()));
        }
    }
    for w in widths.iter_mut() {
        *w = (*w).min(MAX_W);
    }
    let bs = Style::default().fg(t.table_border);
    let border = |l: &str, m: &str, r: &str| -> Line<'static> {
        let mut s = String::from(l);
        for (i, w) in widths.iter().enumerate() {
            s.push_str(&"─".repeat(w + 2));
            s.push_str(if i + 1 == ncols { r } else { m });
        }
        Line::from(Span::styled(s, bs))
    };
    let cell = |text: &str, w: usize, align: &str| -> String {
        let tw = UnicodeWidthStr::width(text);
        if tw > w {
            format!(" {}…", truncate_to(text, w))
        } else {
            let pad = w - tw;
            match align {
                "center" => {
                    let l = pad / 2;
                    format!(" {}{}{} ", " ".repeat(l), text, " ".repeat(pad - l))
                }
                "right" => format!(" {}{} ", " ".repeat(pad), text),
                _ => format!(" {}{} ", text, " ".repeat(pad)),
            }
        }
    };
    let row_line = |cells: &[String], header: bool| -> Line<'static> {
        let mut spans = vec![Span::styled("│", bs)];
        for i in 0..ncols {
            let txt = cells.get(i).map(|s| s.as_str()).unwrap_or("");
            let al = aligns.get(i).map(|s| s.as_str()).unwrap_or("none");
            let c = cell(txt, widths[i], al);
            let st = if header {
                Style::default().fg(t.table_header).add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(t.fg)
            };
            spans.push(Span::styled(c, st));
            spans.push(Span::styled("│", bs));
        }
        Line::from(spans)
    };
    let mut out = vec![border("┌", "┬", "┐"), row_line(headers, true), border("├", "┼", "┤")];
    for r in rows {
        out.push(row_line(r, false));
    }
    out.push(border("└", "┴", "┘"));
    out
}

fn list_lines(ordered: bool, items: &[ListItem], t: &Theme) -> Vec<Line<'static>> {
    let mut out = Vec::new();
    for (idx, it) in items.iter().enumerate() {
        let mut first = true;
        for raw_line in it.content.split('\n') {
            if first {
                first = false;
                let marker = match it.checked {
                    Some(true) => "☑".to_string(),
                    Some(false) => "☐".to_string(),
                    None => {
                        if ordered {
                            format!("{}.", idx + 1)
                        } else {
                            "•".to_string()
                        }
                    }
                };
                out.push(Line::from(vec![
                    Span::styled("  ", Style::default().fg(t.fg)),
                    Span::styled(format!("{} ", marker), Style::default().fg(t.bullet)),
                    Span::styled(raw_line.to_string(), Style::default().fg(t.fg)),
                ]));
            } else {
                let trimmed = raw_line.trim_start_matches(' ');
                let indent = raw_line.len() - trimmed.len();
                out.push(Line::from(vec![
                    Span::styled(format!("  {}", " ".repeat(indent)), Style::default().fg(t.fg)),
                    Span::styled("• ", Style::default().fg(t.bullet)),
                    Span::styled(trimmed.to_string(), Style::default().fg(t.fg)),
                ]));
            }
        }
    }
    out
}

pub fn render_blocks(blocks: &[Block], t: &Theme) -> Vec<Line<'static>> {
    let mut out: Vec<Line<'static>> = Vec::new();
    for b in blocks {
        match b {
            Block::Paragraph { inline, .. } => {
                let (spans, images) = inline_spans(inline, t);
                if !spans_text(&spans).is_empty() {
                    out.push(Line::from(spans));
                }
                for _ in 0..images * IMAGE_HEIGHT {
                    out.push(Line::from(""));
                }
            }
            Block::Heading { level, content, .. } => {
                out.push(Line::from(Span::styled(content.clone(), t.content_heading(*level))));
            }
            Block::Code { language, content, .. } => {
                let fence = Style::default().fg(t.fence);
                out.push(Line::from(Span::styled(format!("```{}", language.clone().unwrap_or_default()), fence)));
                for l in content.split('\n') {
                    out.push(Line::from(Span::styled(l.to_string(), Style::default().fg(t.code_text))));
                }
                out.push(Line::from(Span::styled("```".to_string(), fence)));
            }
            Block::List { ordered, items } => {
                out.extend(list_lines(*ordered, items, t));
            }
            Block::Table { headers, alignments, rows } => {
                out.extend(table_lines(headers, alignments, rows, t));
            }
            Block::Blockquote { content, .. } => {
                out.push(Line::from(vec![
                    Span::styled("│ ", Style::default().fg(t.quote)),
                    Span::styled(content.clone(), Style::default().fg(t.quote).add_modifier(Modifier::ITALIC)),
                ]));
            }
            Block::HorizontalRule => {
                out.push(Line::from(Span::styled("─".repeat(60), Style::default().fg(t.hr))));
            }
            Block::Image { .. } => {
                for _ in 0..IMAGE_HEIGHT {
                    out.push(Line::from(""));
                }
            }
            Block::Details { summary, .. } => {
                out.push(Line::from(vec![
                    Span::styled("▶ ", Style::default().fg(t.bullet)),
                    Span::styled(summary.clone(), Style::default().fg(t.fg)),
                ]));
            }
        }
        out.push(Line::from(""));
    }
    out
}
