                    Span::styled(content.clone(), Style::default().fg(t.quote).add_modifier(Modifier::ITALIC)),
                ]));
            }
            Block::HorizontalRule => {
                out.push(Line::from(Span::styled("─".repeat(60), Style::default().fg(t.hr))));
            }
            Block::Image { .. } => {
                for _ in 0..IMAGE_HEIGHT {
                    out.push(Line::from(""));
                }
            }
            Block::Details { summary, .. } => {
                out.push(Line::from(vec![
                    Span::styled("▶ ", Style::default().fg(t.bullet)),
                    Span::styled(summary.clone(), Style::default().fg(t.fg)),
                ]));
            }
        }
        out.push(Line::from(""));
    }
    out
}
