//! Application state, key handling and drawing.
use super::content::render_blocks;
use super::help::{HelpLine, HELP};
use super::theme::{ocean_dark, Theme};
use crate::blocks;
use crate::doc::Document;
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Constraint, Layout, Margin, Rect};
use ratatui::style::{Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{
    Block, Borders, Clear, List, ListItem, ListState, Paragraph, Scrollbar, ScrollbarOrientation, ScrollbarState,
    Wrap,
};
use ratatui::Frame;

#[derive(Clone, Copy, PartialEq)]
pub enum Focus {
    Outline,
    Content,
}

pub struct H {
    pub level: u8,
    pub text: String,
    pub parent: Option<usize>,
    pub children: Vec<usize>,
    pub content: String,
    pub raw: String,
}

#[derive(Clone)]
pub struct SearchState {
    pub query: String,
    pub editing: bool,
    pub outline: bool,
}

pub struct App {
    pub doc: Document,
    pub name: String,
    pub hs: Vec<H>,
    pub collapsed: Vec<bool>,
    pub sel: usize,
    pub focus: Focus,
    pub scroll: usize,
    pub outline_shown: bool,
    pub outline_pct: u16,
    pub help: bool,
    pub help_scroll: usize,
    pub msg: Option<String>,
    pub raw: bool,
    pub todo_filter: bool,
    pub theme: Theme,
    pub quit: bool,
    pub list_state: ListState,
    pub content_height: usize,
    pub content_lines_len: usize,
    pub help_height: usize,
    pub search: Option<SearchState>,
    pub filter_text: Option<String>,
    pub count: Option<usize>,
}

fn build_hs(doc: &Document) -> Vec<H> {
    let hs = &doc.headings;
    let content = &doc.content;
    let mut out: Vec<H> = Vec::new();
    let mut stack: Vec<usize> = Vec::new();
    for (i, h) in hs.iter().enumerate() {
        while let Some(&top) = stack.last() {
            if hs[top].level >= h.level {
                stack.pop();
            } else {
                break;
            }
        }
        let parent = stack.last().cloned();
        let next = hs[i + 1..].iter().find(|n| n.level <= h.level).map(|n| n.offset).unwrap_or(content.len());
        let cs = doc.content_start(h);
        let body = if cs <= next { content[cs..next].trim().to_string() } else { String::new() };
        let raw = if cs <= next { content[cs..next].trim_end().to_string() } else { String::new() };
        out.push(H { level: h.level, text: h.text.clone(), parent, children: vec![], content: body, raw });
        if let Some(p) = parent {
            out[p].children.push(i);
        }
        stack.push(i);
    }
    out
}

impl App {
    pub fn new(doc: Document, name: String, _theme: Option<String>) -> App {
        let hs = build_hs(&doc);
        let n = hs.len();
        let mut ls = ListState::default();
        ls.select(Some(0));
        App {
            doc,
            name,
            hs,
            collapsed: vec![false; n],
            sel: 0,
            focus: Focus::Outline,
            scroll: 0,
            outline_shown: true,
            outline_pct: 30,
            help: false,
            help_scroll: 0,
            msg: None,
            raw: false,
            todo_filter: false,
            theme: ocean_dark(),
            quit: false,
            list_state: ls,
            content_height: 0,
            content_lines_len: 0,
            help_height: 0,
            search: None,
            filter_text: None,
            count: None,
        }
    }

    fn has_open_todo(&self, i: usize) -> bool {
        let c = &self.hs[i].content;
        c.lines().any(|l| {
            let t = l.trim_start();
            t.starts_with("- [ ]") || t.starts_with("* [ ]") || t.starts_with("+ [ ]")
        })
    }

    pub fn visible(&self) -> Vec<usize> {
        let mut out = Vec::new();
        if let Some(f) = &self.filter_text {
            let fl = f.to_lowercase();
            for (i, h) in self.hs.iter().enumerate() {
                if h.text.to_lowercase().contains(&fl) {
                    out.push(i);
                }
            }
            return out;
        }
        if self.todo_filter {
            for i in 0..self.hs.len() {
                if self.has_open_todo(i) {
                    out.push(i);
                }
            }
            return out;
        }
        for i in 0..self.hs.len() {
            let mut p = self.hs[i].parent;
            let mut hidden = false;
            while let Some(pi) = p {
                if self.collapsed[pi] {
                    hidden = true;
                    break;
                }
                p = self.hs[pi].parent;
            }
            if !hidden {
                out.push(i);
            }
        }
        out
    }

    fn selected_heading(&self) -> Option<usize> {
        let v = self.visible();
        v.get(self.sel).cloned()
    }

    fn content_lines(&self) -> Vec<Line<'static>> {
        let hi = match self.selected_heading() {
            Some(h) => h,
            None => return vec![],
        };
        if self.raw {
            return self.raw_lines(hi);
        }
        let blocks = blocks::build_blocks(&self.hs[hi].content, 1);
        render_blocks(&blocks, &self.theme)
    }

    fn raw_lines(&self, hi: usize) -> Vec<Line<'static>> {
        let t = &self.theme;
        let mut out = Vec::new();
        for (i, l) in self.hs[hi].content.lines().enumerate() {
            out.push(Line::from(vec![
                Span::styled(format!("{:>4} │ ", i + 1), Style::default().fg(t.scrollbar)),
                Span::styled(l.to_string(), Style::default().fg(t.fg)),
            ]));
        }
        out
    }

    fn set_sel(&mut self, s: usize) {
        let n = self.visible().len();
        if n == 0 {
            self.sel = 0;
            return;
        }
        let s = s.min(n - 1);
        if s != self.sel {
            self.scroll = 0;
        }
        self.sel = s;
    }

    pub fn handle_key(&mut self, k: KeyEvent) {
        let had_msg = self.msg.take().is_some();
        let _ = had_msg;
        if self.help {
            match k.code {
                KeyCode::Esc | KeyCode::Char('?') | KeyCode::Char('q') => self.help = false,
                KeyCode::Char('j') | KeyCode::Down => {
                    let max = HELP.len().saturating_sub(1);
                    if self.help_scroll < max {
                        self.help_scroll += 1;
                    }
                }
                KeyCode::Char('k') | KeyCode::Up => self.help_scroll = self.help_scroll.saturating_sub(1),
                _ => {}
            }
            return;
        }
        if let Some(s) = self.search.clone() {
            if s.editing {
                match k.code {
                    KeyCode::Esc => {
                        if s.outline {
                            self.filter_text = None;
                        }
                        self.search = None;
                    }
                    KeyCode::Enter => {
                        if let Some(ss) = self.search.as_mut() {
                            ss.editing = false;
                        }
                    }
                    KeyCode::Backspace => {
                        if let Some(ss) = self.search.as_mut() {
                            ss.query.pop();
                        }
                        self.after_query_change();
                    }
                    KeyCode::Char('u') if k.modifiers.contains(KeyModifiers::CONTROL) => {
                        if let Some(ss) = self.search.as_mut() {
                            ss.query.clear();
                        }
                        self.after_query_change();
                    }
                    KeyCode::Char(c) => {
                        if let Some(ss) = self.search.as_mut() {
                            ss.query.push(c);
                        }
                        self.after_query_change();
                    }
                    _ => {}
                }
                return;
            } else if k.code == KeyCode::Esc {
                if s.outline {
                    self.filter_text = None;
                }
                self.search = None;
                return;
            }
        }
        let n = self.visible().len();
        if self.focus == Focus::Outline {
            match k.code {
                KeyCode::Char('q') | KeyCode::Esc => self.quit = true,
                KeyCode::Char('j') | KeyCode::Down => {
                    let c = self.count.take().unwrap_or(1);
                    self.set_sel(self.sel + c);
                }
                KeyCode::Char('k') | KeyCode::Up => {
                    let c = self.count.take().unwrap_or(1);
                    self.set_sel(self.sel.saturating_sub(c));
                }
                KeyCode::Char('g') | KeyCode::Home => self.set_sel(0),
                KeyCode::Char('G') | KeyCode::End => self.set_sel(n.saturating_sub(1)),
                KeyCode::Char('p') => {
                    if let Some(hi) = self.selected_heading() {
                        if let Some(p) = self.hs[hi].parent {
                            if let Some(pos) = self.visible().iter().position(|&x| x == p) {
                                self.set_sel(pos);
                            }
                        }
                    }
                }
                KeyCode::Enter | KeyCode::Char(' ') => {
                    if let Some(hi) = self.selected_heading() {
                        if !self.hs[hi].children.is_empty() {
                            self.collapsed[hi] = !self.collapsed[hi];
                        }
                    }
                }
                KeyCode::Char('l') | KeyCode::Right => {
                    if let Some(hi) = self.selected_heading() {
                        self.collapsed[hi] = false;
                    }
                }
                KeyCode::Char('h') | KeyCode::Left => {
                    if let Some(hi) = self.selected_heading() {
                        if !self.hs[hi].children.is_empty() && !self.collapsed[hi] {
                            self.collapsed[hi] = true;
                        } else if let Some(p) = self.hs[hi].parent {
                            if let Some(pos) = self.visible().iter().position(|&x| x == p) {
                                self.set_sel(pos);
                            }
                        }
                    }
                }
                KeyCode::Tab => self.focus = Focus::Content,
                KeyCode::Char(c) if c.is_ascii_digit() && c != '0' || (c == '0' && self.count.is_some()) => {
                    let d = c.to_digit(10).unwrap() as usize;
                    self.count = Some(self.count.unwrap_or(0) * 10 + d);
                    return;
                }
                _ => self.common_key(k),
            }
        } else {
            let max_scroll = self.content_lines_len.saturating_sub(self.content_height);
            match k.code {
                KeyCode::Char('q') | KeyCode::Esc => self.quit = true,
                KeyCode::Char('j') | KeyCode::Down => {
                    if self.scroll < max_scroll {
                        self.scroll += 1;
                    }
                }
                KeyCode::Char('k') | KeyCode::Up => self.scroll = self.scroll.saturating_sub(1),
                KeyCode::Char('g') | KeyCode::Home => self.scroll = 0,
                KeyCode::Char('G') | KeyCode::End => self.scroll = max_scroll,
                KeyCode::Char('d') | KeyCode::PageDown => {
                    self.scroll = (self.scroll + self.content_height / 2).min(max_scroll);
                }
                KeyCode::Char('u') | KeyCode::PageUp => {
                    self.scroll = self.scroll.saturating_sub(self.content_height / 2);
                }
                KeyCode::Tab => {
                    if self.outline_shown {
                        self.focus = Focus::Outline;
                    }
                }
                _ => self.common_key(k),
            }
        }
        self.count = None;
    }

    fn after_query_change(&mut self) {
        if let Some(s) = &self.search {
            if s.outline {
                self.filter_text = Some(s.query.clone());
                self.sel = 0;
                self.scroll = 0;
            }
        }
    }

    fn common_key(&mut self, k: KeyEvent) {
        match k.code {
            KeyCode::Char('?') => {
                self.help = true;
                self.help_scroll = 0;
            }
            KeyCode::Char('w') => {
                self.outline_shown = !self.outline_shown;
                self.focus = if self.outline_shown { Focus::Outline } else { Focus::Content };
            }
            KeyCode::Char(']') => {
                self.outline_pct = match self.outline_pct {
                    20 => 30,
                    30 => 40,
                    _ => 20,
                };
                self.msg = Some(format!("Width: {}%", self.outline_pct));
            }
            KeyCode::Char('[') => {
                self.outline_pct = match self.outline_pct {
                    40 => 30,
                    30 => 20,
                    _ => 40,
                };
                self.msg = Some(format!("Width: {}%", self.outline_pct));
            }
            KeyCode::Char('r') => {
                self.raw = !self.raw;
                self.scroll = 0;
                self.msg = Some(if self.raw { "Raw source view enabled".into() } else { "Rendered view enabled".into() });
            }
            KeyCode::Char('t') => {
                self.todo_filter = !self.todo_filter;
                self.sel = 0;
                self.scroll = 0;
                if self.todo_filter {
                    let c = self.visible().len();
                    self.msg = Some(format!("Todo filter ON: {} headings with open todos", c));
                } else {
                    self.msg = Some("Todo filter OFF".into());
                }
            }
            KeyCode::Char('/') => {
                self.search = Some(SearchState { query: String::new(), editing: true, outline: false });
            }
            KeyCode::Char('s') => {
                self.search = Some(SearchState { query: String::new(), editing: true, outline: true });
            }
            _ => {}
        }
    }

    // ---------------- drawing ----------------

    pub fn draw(&mut self, f: &mut Frame) {
        let t = self.theme.clone();
        let area = f.area();
        f.render_widget(Block::default().style(t.base()), area);
        let rows = Layout::vertical([
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Min(0),
            Constraint::Length(1),
            Constraint::Length(1),
        ])
        .split(area);
        // title
        let title = format!("treemd - {} - {} headings", self.name, self.hs.len());
        f.render_widget(
            Paragraph::new(Line::from(Span::styled(title, Style::default().fg(t.title).add_modifier(Modifier::BOLD)))),
            rows[0],
        );
        let sep = "─".repeat(area.width as usize);
        f.render_widget(
            Paragraph::new(Line::from(Span::styled(sep, Style::default().fg(t.title).add_modifier(Modifier::BOLD)))),
            rows[1],
        );
        let mut main = rows[2];
        if let Some(s) = &self.search {
            let parts = Layout::vertical([Constraint::Length(3), Constraint::Min(0)]).split(main);
            self.draw_search(f, parts[0], s.clone());
            main = parts[1];
        }
        if self.outline_shown {
            let cols = Layout::horizontal([
                Constraint::Percentage(self.outline_pct),
                Constraint::Percentage(100 - self.outline_pct),
            ])
            .split(main);
            self.draw_outline(f, cols[0]);
            self.draw_content(f, cols[1]);
        } else {
            self.draw_content(f, main);
        }
        self.draw_status(f, rows[3]);
        self.draw_hints(f, rows[4]);
        if self.help {
            self.draw_help(f, area);
        }
    }

    fn draw_search(&self, f: &mut Frame, area: Rect, s: SearchState) {
        let t = &self.theme;
        let title = if s.outline {
            " Outline Search (Tab: switch to Content) "
        } else {
            " Content Search (Tab: switch to Outline) "
        };
        let label = if s.outline { "Filter" } else { "Find" };
        let hint = if s.editing { "(Esc, Ctrl+U)" } else { "(Esc, Tab, /: edit)" };
        let cursor = if s.editing { "_" } else { "" };
        let mut text = format!("{}: {}{}", label, s.query, cursor);
        if !s.outline && !s.query.is_empty() {
            let (cur, total) = self.match_count(&s.query);
            if total > 0 {
                text.push_str(&format!(" [{}/{}]", cur, total));
            }
        }
        text.push_str("  ");
        text.push_str(hint);
        let block = Block::default()
            .borders(Borders::ALL)
            .title(title)
            .border_style(Style::default().fg(t.border_focus));
        f.render_widget(Paragraph::new(Line::from(Span::styled(text, Style::default().fg(t.fg)))).block(block), area);
    }

    fn match_count(&self, q: &str) -> (usize, usize) {
        let ql = q.to_lowercase();
        let mut total = 0;
        if let Some(hi) = self.selected_heading() {
            let c = self.hs[hi].content.to_lowercase();
            total = c.matches(&ql).count();
        }
        (if total > 0 { 1 } else { 0 }, total)
    }

    fn draw_outline(&mut self, f: &mut Frame, area: Rect) {
        let t = self.theme.clone();
        let focused = self.focus == Focus::Outline;
        let block = Block::default()
            .borders(Borders::ALL)
            .title(" Outline ")
            .border_style(Style::default().fg(if focused { t.border_focus } else { t.border }));
        let vis = self.visible();
        let items: Vec<ListItem> = vis
            .iter()
            .map(|&i| {
                let h = &self.hs[i];
                let indent = "  ".repeat((h.level as usize).saturating_sub(1));
                let exp = if h.children.is_empty() || self.filter_text.is_some() || self.todo_filter {
                    "  "
                } else if self.collapsed[i] {
                    "▶ "
                } else {
                    "▼ "
                };
                let text = format!("{}{}{} {}", indent, exp, "#".repeat(h.level as usize), h.text);
                ListItem::new(Line::from(Span::styled(text, Style::default().fg(t.heading_color(h.level)))))
            })
            .collect();
        let list = List::new(items)
            .block(block)
            .style(Style::default().fg(t.fg))
            .highlight_symbol("► ")
            .highlight_style(Style::default().fg(t.sel_fg).bg(t.sel_bg).add_modifier(Modifier::BOLD));
        if vis.is_empty() {
            self.list_state.select(None);
        } else {
            self.list_state.select(Some(self.sel.min(vis.len() - 1)));
        }
        f.render_stateful_widget(list, area, &mut self.list_state);
        let mut st = ScrollbarState::new(vis.len()).position(self.sel);
        f.render_stateful_widget(
            Scrollbar::new(ScrollbarOrientation::VerticalRight).style(Style::default().fg(t.scrollbar)),
            area.inner(Margin { vertical: 1, horizontal: 0 }),
            &mut st,
        );
    }

    fn draw_content(&mut self, f: &mut Frame, area: Rect) {
        let t = self.theme.clone();
        let focused = self.focus == Focus::Content;
        let title = match self.selected_heading() {
            Some(hi) => {
                if self.raw {
                    format!(" [RAW] {} ", self.hs[hi].text)
                } else {
                    format!(" {} ", self.hs[hi].text)
                }
            }
            None => " Content ".to_string(),
        };
        let block = Block::default()
            .borders(Borders::ALL)
            .title(title)
            .border_style(Style::default().fg(if focused { t.border_focus } else { t.border }));
        let lines = self.content_lines();
        self.content_lines_len = lines.len();
        self.content_height = area.height.saturating_sub(2) as usize;
        let para = Paragraph::new(lines)
            .block(block)
            .style(t.base())
            .wrap(Wrap { trim: false })
            .scroll((self.scroll as u16, 0));
        f.render_widget(para, area);
        let mut st = ScrollbarState::new(self.content_lines_len).position(self.scroll);
        f.render_stateful_widget(
            Scrollbar::new(ScrollbarOrientation::VerticalRight).style(Style::default().fg(t.scrollbar)),
            area.inner(Margin { vertical: 1, horizontal: 0 }),
            &mut st,
        );
    }

    fn draw_status(&self, f: &mut Frame, area: Rect) {
        let t = &self.theme;
        if let Some(m) = &self.msg {
            f.render_widget(Paragraph::new(Line::from(Span::styled(m.clone(), Style::default().fg(t.fg)))), area);
            return;
        }
        let outline = if self.outline_shown { format!("{}%", self.outline_pct) } else { "Hidden".to_string() };
        let pos = if self.focus == Focus::Outline {
            let n = self.visible().len();
            let pct = if n == 0 { 0 } else { (self.sel + 1) * 100 / n };
            format!("[Outline] {}/{} ({}%)", if n == 0 { 0 } else { self.sel + 1 }, n, pct)
        } else {
            let total = self.content_lines_len.max(1);
            let pct = (self.scroll + 1) * 100 / total;
            format!("[Content] Line {} ({}%)", self.scroll + 1, pct)
        };
        let text = format!(" {} • Outline:{} • Theme:{}", pos, outline, t.name);
        f.render_widget(
            Paragraph::new(Line::from(Span::styled(text, Style::default().fg(t.status_fg).bg(t.status_bg))))
                .style(Style::default().bg(t.status_bg)),
            area,
        );
    }

    fn draw_hints(&self, f: &mut Frame, area: Rect) {
        let t = &self.theme;
        let pairs: Vec<(&str, &str)> = if self.search.is_some() && !self.search.as_ref().unwrap().outline {
            vec![("n/N", "Next/Prev"), ("Tab", "Outline Search"), ("Enter", "Accept"), ("Esc", "Cancel")]
        } else if self.focus == Focus::Outline {
            vec![
                ("j/k", "Navigate"),
                ("Enter", "Select"),
                ("/", "Search"),
                ("i", "Interactive"),
                ("f", "Links"),
                ("?", "Help"),
            ]
        } else {
            vec![("j/k", "Scroll"), ("/", "Search"), ("i", "Interactive"), ("f", "Links"), ("y", "Copy"), ("?", "Help")]
        };
        let mut spans = Vec::new();
        for (k, d) in pairs {
            spans.push(Span::styled(
                format!(" {} ", k),
                Style::default().fg(t.hint_key).bg(t.status_bg).add_modifier(Modifier::BOLD),
            ));
            spans.push(Span::styled(format!("{} ", d), Style::default().fg(t.hint_desc).bg(t.bg)));
        }
        f.render_widget(Paragraph::new(Line::from(spans)), area);
    }

    fn draw_help(&mut self, f: &mut Frame, area: Rect) {
        let t = self.theme.clone();
        let v = Layout::vertical([
            Constraint::Percentage(10),
            Constraint::Percentage(80),
            Constraint::Percentage(10),
        ])
        .split(area);
        let h = Layout::horizontal([
            Constraint::Percentage(15),
            Constraint::Percentage(70),
            Constraint::Percentage(15),
        ])
        .split(v[1]);
        let popup = h[1];
        f.render_widget(Clear, popup);
        let mut lines: Vec<Line> = Vec::new();
        for hl in HELP {
            let l = match hl {
                HelpLine::Title(s) => Line::from(Span::styled(*s, Style::default().add_modifier(Modifier::BOLD))),
                HelpLine::Hint(s) => Line::from(Span::styled(
                    *s,
                    Style::default().fg(t.dim).add_modifier(Modifier::ITALIC),
                )),
                HelpLine::Blank => Line::from(""),
                HelpLine::Section(s) => Line::from(Span::styled(*s, Style::default().add_modifier(Modifier::BOLD))),
                HelpLine::Key(k, d) => Line::from(vec![
                    Span::styled(format!("  {:<11}", k), Style::default().fg(t.help_key)),
                    Span::raw(*d),
                ]),
                HelpLine::Note(s) => Line::from(Span::raw(*s)),
            };
            lines.push(l);
        }
        let n = lines.len();
        self.help_height = popup.height.saturating_sub(2) as usize;
        let block = Block::default()
            .borders(Borders::ALL)
            .title(" Help ")
            .border_style(Style::default().fg(t.border_focus))
            .style(Style::default().bg(t.popup_bg));
        f.render_widget(
            Paragraph::new(lines).block(block).wrap(Wrap { trim: false }).scroll((self.help_scroll as u16, 0)),
            popup,
        );
        let mut st = ScrollbarState::new(n).position(self.help_scroll);
        f.render_stateful_widget(
            Scrollbar::new(ScrollbarOrientation::VerticalRight).style(Style::default().fg(t.border_focus)),
            popup.inner(Margin { vertical: 1, horizontal: 0 }),
            &mut st,
        );
    }
}
