/// Vertical scrollbar on the right edge of `area` (ratatui 0.29 algorithm).
pub fn draw_scrollbar(f: &mut Frame, area: Rect, content_len: usize, position: usize, style: Style) {
    if content_len == 0 || area.height < 3 || area.width == 0 {
        return;
    }
    let x = area.x + area.width - 1;
    let track = (area.height - 2) as f64;
    let viewport = area.height as f64;
    let position = position.min(content_len.saturating_sub(1)) as f64;
    let max_position = content_len.saturating_sub(1) as f64;
    let max_vp = max_position + viewport;
    let start = (position * track / max_vp).round().clamp(0.0, track - 1.0);
    let end = ((position + viewport) * track / max_vp).round().clamp(0.0, track);
    let start = start as u16;
    let end = (end as u16).max(start + 1);
    let buf = f.buffer_mut();
    let top = area.y;
    if let Some(c) = buf.cell_mut((x, top)) {
        c.set_symbol("↑");
        c.set_style(style);
    }
    for i in 0..(area.height - 2) {
        let sym = if i >= start && i < end { "█" } else { "║" };
        if let Some(c) = buf.cell_mut((x, top + 1 + i)) {
            c.set_symbol(sym);
            c.set_style(style);
        }
    }
    if let Some(c) = buf.cell_mut((x, top + area.height - 1)) {
        c.set_symbol("↓");
        c.set_style(style);
    }
}
