//! Minimal persisted configuration (~/.config/treemd/config.toml).
use std::path::PathBuf;

fn config_path() -> Option<PathBuf> {
    dirs::config_dir().map(|d| d.join("treemd").join("config.toml"))
}

pub fn load_width() -> Option<u16> {
    let p = config_path()?;
    let s = std::fs::read_to_string(p).ok()?;
    let v: toml::Value = toml::from_str(&s).ok()?;
    let w = v.get("ui")?.get("outline_width")?.as_integer()?;
    Some(w as u16)
}

const DEFAULT: &str = r#"[ui]
theme = "OceanDark"
outline_width = 30
tree_style = "compact"

[terminal]
color_mode = "auto"
warned_terminal_app = false

[theme]

[keybindings]

[editor]

[images]
enabled = true

[content]
hide_frontmatter = true
hide_latex = true
latex_aggressive = false
"#;

pub fn save_width(w: u16) {
    let p = match config_path() {
        Some(p) => p,
        None => return,
    };
    let existing = std::fs::read_to_string(&p).unwrap_or_else(|_| DEFAULT.to_string());
    let mut out = String::new();
    let mut replaced = false;
    for line in existing.lines() {
        if line.trim_start().starts_with("outline_width") && !replaced {
            out.push_str(&format!("outline_width = {}\n", w));
            replaced = true;
        } else {
            out.push_str(line);
            out.push('\n');
        }
    }
    if let Some(dir) = p.parent() {
        let _ = std::fs::create_dir_all(dir);
    }
    let _ = std::fs::write(&p, out);
}
